_NESTED_FIXTURES = os.path.join(
    _HERE, "fixtures", "measurement")


def _nested_fixture_events(name):
    path = os.path.join(_NESTED_FIXTURES, name, "raw-events.jsonl")
    with open(path) as fh:
        return [json.loads(line) for line in fh if line.strip()]


def _materialize_nested_fixture_repo(name, root):
    """Build one fixture's real git state and return its boundary delta."""
    with open(os.path.join(
            _NESTED_FIXTURES, name, "repo-fixture.json")) as fh:
        fixture = json.load(fh)
    repo = os.path.join(root, "repo")
    os.mkdir(repo)

    def git(*args):
        return subprocess.run(
            ["git", "-C", repo] + list(args), stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, check=True)

    git("init")
    git("config", "user.email", "fixture@example.invalid")
    git("config", "user.name", "Fixture")
    git("config", "commit.gpgsign", "false")
    for relative, content in fixture["initial"].items():
        path = os.path.join(repo, relative)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        Path(path).write_text(content)
    git("add", ".")
    git("commit", "-m", "fixture")
    scope = action_policy.OwnedScope(repo_roots=(repo,))
    before = delta_store.snapshot(scope)
    for relative, content in fixture["writes"].items():
        path = os.path.join(repo, relative)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        Path(path).write_text(content)
    for relative in fixture["deletes"]:
        os.unlink(os.path.join(repo, relative))
    result = delta_store.diff(before, delta_store.snapshot(scope))
    expected = {
        key: sorted(os.path.realpath(os.path.join(repo, relative))
                    for relative in fixture["expected"][key])
        for key in ("added", "modified", "deleted")
    }
    return result, expected


class FlagAssemblyTest(unittest.TestCase):
    def test_claude_mode_flags(self):
        self.assertEqual(bridge.claude_mode_flags("plan", True),
                         ["--permission-mode", "plan"])
        self.assertEqual(bridge.claude_mode_flags("plan", False),
                         ["--permission-mode", "plan"])
        self.assertEqual(bridge.claude_mode_flags("implement", True),
                         ["--dangerously-skip-permissions"])
        self.assertEqual(bridge.claude_mode_flags("implement", False),
                         ["--permission-mode", "acceptEdits"])

    def test_codex_mode_flags(self):
        # codex exec has no --ask-for-approval; approval is governed by sandbox.
        self.assertEqual(bridge.codex_mode_flags("plan", True),
                         ["--sandbox", "read-only"])
        self.assertEqual(bridge.codex_mode_flags("implement", True),
                         ["--dangerously-bypass-approvals-and-sandbox"])
        self.assertEqual(bridge.codex_mode_flags("implement", False),
                         ["--sandbox", "workspace-write"])

    def test_build_claude_command_is_duplex(self):
        cmd = bridge.build_claude_command("roles/scout.md", "plan", True)
        for flag in ("-p", "--input-format", "stream-json", "--output-format",
                     "--verbose", "--replay-user-messages",
                     "--append-system-prompt-file"):
            self.assertIn(flag, cmd)
        self.assertIn("roles/scout.md", cmd)
        self.assertEqual(cmd[0], "claude")
        # interactive question tool is blocked (auto-"skipped" in headless -p)
        self.assertIn("--disallowedTools", cmd)
        self.assertIn("AskUserQuestion", cmd)
        # ORCH-001: only the cowork-owned empty MCP config is ever loaded.
        self.assertIn("--strict-mcp-config", cmd)
        self.assertEqual(cmd[cmd.index("--mcp-config") + 1],
                         bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)

    def test_build_codex_command(self):
        cmd = bridge.build_codex_command("PROMPT", "plan", True)
        self.assertEqual(cmd[:4], ["codex", "exec", "--json", "--skip-git-repo-check"])
        self.assertIn("--sandbox", cmd)
        self.assertEqual(cmd[-1], "PROMPT")

    def test_guarded_claude_uses_only_explicit_cowork_settings(self):
        cmd = bridge.build_claude_command(
            "roles/scout.md", "plan", False,
            session_id="11111111-1111-4111-8111-111111111111",
            guard_settings_path="/private/guard-settings.json",
            delegation_allowed=False)
        index = cmd.index("--setting-sources")
        self.assertEqual(cmd[index + 1], "")
        self.assertEqual(
            cmd[cmd.index("--settings") + 1],
            "/private/guard-settings.json")
        self.assertIn("Agent", cmd)
        self.assertIn("Task", cmd)
        self.assertFalse(any(
            str(part).startswith("CLAUDE_CONFIG_DIR=") for part in cmd))
        # ORCH-001: the MCP-free flag pair is independent of the guard
        # settings block and present on the guarded launch too.
        self.assertIn("--strict-mcp-config", cmd)
        self.assertEqual(cmd[cmd.index("--mcp-config") + 1],
                         bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)

    def test_guarded_codex_fresh_and_resume_share_fail_closed_flags(self):
        fresh = bridge.build_codex_command(
            "PROMPT", "implement", False, guarded=True)
        resume = bridge.build_codex_resume_command(
            "thread-abc", "NEXT", "implement", False, guarded=True)
        for command in (fresh, resume):
            self.assertIn("--ignore-user-config", command)
            self.assertIn("--ignore-rules", command)
            self.assertIn("--dangerously-bypass-hook-trust", command)
            self.assertIn("--strict-config", command)
            disable = command.index("--disable")
            self.assertEqual(command[disable + 1], "multi_agent")
            self.assertIn("agents.enabled=false", self._c_values(command))
            self.assertIn("project_doc_max_bytes=0", self._c_values(command))
            # ORCH-001: the fail-closed MCP override rides fresh AND resume.
            self.assertIn("mcp_servers={}", self._c_values(command))
            self.assertTrue(any(
                value.startswith("projects.")
                and value.endswith('.trust_level="untrusted"')
                for value in self._c_values(command)))

    def test_codex_resume_uses_explicit_id_never_last(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "plan", True)
        self.assertEqual(cmd[:5],
                         ["codex", "exec", "resume", "--json",
                          "--skip-git-repo-check"])
        # explicit id present, prompt strictly last, never --last.
        self.assertIn("thread-abc", cmd)
        self.assertEqual(cmd[-1], "next")
        self.assertNotIn("--last", cmd)
        # resume rejects --sandbox/--add-dir; permissions re-applied via -c.
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)

    def _add_dir_pair(self, cmd):
        # Return the (flag, value) pair following --add-dir, or None.
        if "--add-dir" not in cmd:
            return None
        i = cmd.index("--add-dir")
        return (cmd[i], cmd[i + 1])

    def test_claude_command_extra_writable_dir(self):
        # Granted on BOTH the fresh (session_id) and resume (resume_id) forms.
        fresh = bridge.build_claude_command(
            "roles/scout.md", "implement", False, session_id="sid",
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(fresh),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        resume = bridge.build_claude_command(
            "roles/scout.md", "implement", False, resume_id="rid",
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(resume),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        # Byte-identical to today when the param is omitted/None.
        self.assertEqual(
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid"),
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid",
                                        extra_writable_dir=None))
        self.assertNotIn(
            "--add-dir",
            bridge.build_claude_command("roles/scout.md", "implement", False,
                                        session_id="sid"))

    def test_codex_command_extra_writable_dir(self):
        cmd = bridge.build_codex_command(
            "PROMPT", "implement", False,
            extra_writable_dir="/home/u/.cowork/sessions/S")
        self.assertEqual(self._add_dir_pair(cmd),
                         ("--add-dir", "/home/u/.cowork/sessions/S"))
        self.assertEqual(cmd[-1], "PROMPT")  # prompt stays last
        # Byte-identical to today when the param is omitted/None.
        self.assertEqual(
            bridge.build_codex_command("PROMPT", "implement", False),
            bridge.build_codex_command("PROMPT", "implement", False,
                                       extra_writable_dir=None))
        self.assertNotIn(
            "--add-dir",
            bridge.build_codex_command("PROMPT", "implement", False))

    def _c_values(self, cmd):
        # Return the list of values following each `-c` flag.
        return [cmd[i + 1] for i, tok in enumerate(cmd) if tok == "-c"]

    def test_codex_resume_mode_args_branches(self):
        # plan -> read-only via -c.
        self.assertEqual(
            bridge.codex_resume_mode_args("plan", True),
            ["-c", 'sandbox_mode="read-only"'])
        self.assertEqual(
            bridge.codex_resume_mode_args("plan", False),
            ["-c", 'sandbox_mode="read-only"'])
        # implement + yolo -> bypass flag, no sandbox/add-dir.
        self.assertEqual(
            bridge.codex_resume_mode_args("implement", True),
            ["--dangerously-bypass-approvals-and-sandbox"])
        # implement + no-yolo, no dir -> workspace-write only.
        self.assertEqual(
            bridge.codex_resume_mode_args("implement", False),
            ["-c", 'sandbox_mode="workspace-write"'])
        # implement + no-yolo + dir -> workspace-write + json-encoded root.
        self.assertEqual(
            bridge.codex_resume_mode_args(
                "implement", False,
                extra_writable_dir="/home/u/.cowork/sessions/S"),
            ["-c", 'sandbox_mode="workspace-write"',
             "-c",
             'sandbox_workspace_write.writable_roots='
             '["/home/u/.cowork/sessions/S"]'])

    def test_codex_resume_implement_yolo(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "implement", True)
        self.assertIn("--dangerously-bypass-approvals-and-sandbox", cmd)
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)
        self.assertIn("thread-abc", cmd)
        self.assertEqual(cmd[-1], "next")
        self.assertNotIn("--last", cmd)

    def test_codex_resume_implement_no_yolo_regrants_root(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "implement", False,
            extra_writable_dir="/home/u/.cowork/sessions/S")
        cvals = self._c_values(cmd)
        self.assertIn('sandbox_mode="workspace-write"', cvals)
        self.assertIn(
            'sandbox_workspace_write.writable_roots='
            '["/home/u/.cowork/sessions/S"]', cvals)
        self.assertNotIn("--sandbox", cmd)
        self.assertNotIn("--add-dir", cmd)
        self.assertEqual(cmd[-1], "next")  # prompt stays last
        self.assertNotIn("--last", cmd)

    def test_codex_resume_plan_read_only(self):
        cmd = bridge.build_codex_resume_command(
            "thread-abc", "next", "plan", False)
        self.assertIn('sandbox_mode="read-only"', self._c_values(cmd))
        self.assertEqual(cmd[-1], "next")


class ModelEffortFlagTest(unittest.TestCase):
    """Per-role model + thinking-effort pins on the assembled CLI commands."""

    def _c_values(self, cmd):
        return [cmd[i + 1] for i, tok in enumerate(cmd) if tok == "-c"]

    def test_claude_command_model_effort(self):
        cmd = bridge.build_claude_command(
            "roles/scout.md", "implement", True, session_id="sid",
            model="opus", effort="high")
        self.assertEqual(cmd[cmd.index("--model") + 1], "opus")
        self.assertEqual(cmd[cmd.index("--effort") + 1], "high")
        # Unset -> byte-identical to today (the CLI's own defaults apply).
        self.assertEqual(
            bridge.build_claude_command("roles/scout.md", "implement", True,
                                        session_id="sid"),
            bridge.build_claude_command("roles/scout.md", "implement", True,
                                        session_id="sid", model=None,
                                        effort=None))
        self.assertNotIn(
            "--model", bridge.build_claude_command(
                "roles/scout.md", "implement", True, session_id="sid"))

    def test_codex_model_args_shared_by_fresh_and_resume(self):
        self.assertEqual(bridge.codex_model_args(), [])
        # -c (not -m) so fresh and resume take the identical spelling: resume
        # rejects -m but accepts -c.
        self.assertEqual(
            bridge.codex_model_args("gpt-5.4-codex", "high"),
            ["-c", 'model="gpt-5.4-codex"',
             "-c", 'model_reasoning_effort="high"'])
        fresh = bridge.build_codex_command(
            "P", "implement", True, model="gpt-5.4-codex", effort="high")
        resume = bridge.build_codex_resume_command(
            "thread-1", "P", "implement", True, model="gpt-5.4-codex",
            effort="high")
        for cmd in (fresh, resume):
            self.assertIn('model="gpt-5.4-codex"', self._c_values(cmd))
            self.assertIn('model_reasoning_effort="high"',
                          self._c_values(cmd))
            self.assertEqual(cmd[-1], "P")  # prompt stays last
        self.assertNotIn("-m", fresh)
        # Unset -> byte-identical to today.
        self.assertEqual(
            bridge.build_codex_command("P", "implement", True),
            bridge.build_codex_command("P", "implement", True,
                                       model=None, effort=None))


class OpencodeBridgeTest(unittest.TestCase):
    """opencode agent-file generation, command assembly, and event parsing."""

    # ORCH-001: the exact `tools:` block every cowork opencode agent file
    # carries — the MCP catch-all deny first, then the native re-allows
    # (last matching rule wins).
    TOOLS_BLOCK = (
        "tools:\n"
        "  task: false\n"
        '  "*_*": false\n'
        "  external_directory: true\n"
        "  read: true\n"
        "  edit: true\n"
        "  write: true\n"
        "  bash: true\n"
        "  grep: true\n"
        "  glob: true\n"
        "  list: true\n"
        "  webfetch: true\n"
        "  skill: true\n"
        "  todowrite: true\n"
        "  todoread: true\n"
        "  apply_patch: true\n")

    def _allow_keys(self, lines):
        """The set of quoted-key texts on every `... : allow` line."""
        keys = set()
        for line in lines:
            stripped = line.strip()
            if stripped.endswith(": allow") and stripped != "webfetch: allow":
                keys.add(stripped[:-len(": allow")])
        return keys

    def test_permission_lines_per_mode(self):
        # Yolo still hard-removes native delegation; --auto applies to the
        # remaining tools only.
        self.assertEqual(
            bridge.opencode_permission_lines("implement", True),
            ["permission:", "  task: deny"])
        # Plan mode with NO declared outputs stays the safe scalar deny
        # (P12): the formatter is a total pure function that never raises.
        plan = bridge.opencode_permission_lines("plan", True)
        self.assertIn("  task: deny", plan)
        self.assertIn("  edit: deny", plan)
        self.assertIn("  bash: ask", plan)  # ask auto-rejects headless
        safe = bridge.opencode_permission_lines("implement", False,
                                                external_dir=True)
        self.assertIn("  edit: allow", safe)
        self.assertIn("  external_directory: allow", safe)
        # plan mode with no declared outputs never grants the external dir
        # either (read-only stays read-only).
        self.assertNotIn(
            "  external_directory: allow",
            bridge.opencode_permission_lines("plan", True, external_dir=True))

    def test_permission_lines_plan_mode_declared_outputs_map(self):
        # Plan mode WITH declared outputs emits an ordered object map: the
        # catch-all denies come first, then one allow per pattern form per
        # declared output (P1, P2); external_directory gets the same
        # deny-first shape, scoped to just the assets dir (P8) — never the
        # flat `external_directory: allow`.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        lines = bridge.opencode_permission_lines(
            "plan", True, declared_outputs=outputs, assets_dir=assets)
        self.assertIn("  task: deny", lines)
        self.assertIn("  edit:", lines)
        self.assertIn("  bash: ask", lines)
        self.assertIn("  webfetch: allow", lines)
        self.assertIn("  external_directory:", lines)
        self.assertNotIn("  external_directory: allow", lines)

        edit_section = lines[lines.index("  edit:"):lines.index("  bash: ask")]
        deny_idx = [i for i, l in enumerate(edit_section)
                   if l.strip().endswith(": deny")]
        allow_idx = [i for i, l in enumerate(edit_section)
                    if l.strip().endswith(": allow")]
        self.assertEqual(len(deny_idx), 2)  # "*" and "**"
        self.assertTrue(deny_idx)
        self.assertTrue(allow_idx)
        self.assertLess(max(deny_idx), min(allow_idx))  # denies precede allows

        expected_edit = set()
        for out in outputs:
            expected_edit.update(bridge._opencode_path_patterns(out, assets))
        self.assertEqual(
            self._allow_keys(edit_section),
            {bridge._opencode_yaml_key(p) for p in expected_edit})

        ext_section = lines[lines.index("  external_directory:"):]
        ext_deny_idx = [i for i, l in enumerate(ext_section)
                        if l.strip().endswith(": deny")]
        ext_allow_idx = [i for i, l in enumerate(ext_section)
                         if l.strip().endswith(": allow")]
        self.assertEqual(len(ext_deny_idx), 2)
        self.assertLess(max(ext_deny_idx), min(ext_allow_idx))
        self.assertEqual(
            self._allow_keys(ext_section),
            {bridge._opencode_yaml_key(p)
             for p in bridge._opencode_dir_patterns(assets)})

    def test_permission_lines_plan_mode_negative_matches(self):
        # A repository path and a non-declared session asset match no allow
        # key — the repository and other roles' artifacts stay read-only.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "scout-review.json"),)
        lines = bridge.opencode_permission_lines(
            "plan", True, declared_outputs=outputs, assets_dir=assets)
        allow_keys = self._allow_keys(lines)

        repo_path = os.path.join(_HERE, "cowork.py")
        for pattern in bridge._opencode_path_patterns(repo_path, assets):
            self.assertNotIn(bridge._opencode_yaml_key(pattern), allow_keys)

        other_asset = os.path.join(assets, "planner.plan.json")
        for pattern in bridge._opencode_path_patterns(other_asset, assets):
            self.assertNotIn(bridge._opencode_yaml_key(pattern), allow_keys)

    def test_agent_markdown_implement_frontmatter_golden(self):
        # Nothing regresses for the configurations that already worked:
        # implement+yolo and implement+no-yolo frontmatter stay byte-exact.
        yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", True, description="d")
        self.assertEqual(
            yolo_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n---\nR\n")
        no_yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", False, description="d")
        self.assertEqual(
            no_yolo_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n  edit: allow\n  bash: ask\n"
            "  webfetch: allow\n---\nR\n")
        no_yolo_ext_md = bridge.opencode_agent_markdown(
            "R", "implement", False, description="d", external_dir=True)
        self.assertEqual(
            no_yolo_ext_md,
            "---\ndescription: d\nmode: primary\n" + self.TOOLS_BLOCK +
            "permission:\n  task: deny\n  edit: allow\n  bash: ask\n"
            "  webfetch: allow\n  external_directory: allow\n---\nR\n")

    @unittest.skipUnless(HAS_YAML, "PyYAML not installed")
    def test_plan_mode_frontmatter_parses_as_structural_deny_first_map(self):
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", True, description="d",
            declared_outputs=outputs, assets_dir=assets)
        self.assertTrue(md.startswith("---\n"))
        fm_text, _, _ = md[len("---\n"):].partition("\n---\n")
        doc = yaml.safe_load(fm_text)
        edit = doc["permission"]["edit"]
        self.assertIsInstance(edit, dict)
        keys = list(edit.keys())
        self.assertEqual(edit[keys[0]], "deny")
        self.assertEqual(edit[keys[1]], "deny")
        self.assertTrue(any(v == "allow" for v in list(edit.values())[2:]))
        ext = doc["permission"]["external_directory"]
        self.assertIsInstance(ext, dict)
        ext_keys = list(ext.keys())
        self.assertEqual(ext[ext_keys[0]], "deny")
        self.assertEqual(ext[ext_keys[1]], "deny")

    @unittest.skipUnless(HAS_YAML, "PyYAML not installed")
    def test_plan_mode_frontmatter_mcp_disabled(self):
        # ORCH-001: the `tools:` map denies every MCP tool via the `"*_*"`
        # catch-all (opencode names MCP tools `<server>_<tool>`) while the
        # native tools cowork roles depend on stay explicitly re-allowed.
        # Deny-first/allow-last: the last matching rule wins, so the denies
        # must precede the re-allows.
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "planner.plan.json"),
                  os.path.join(assets, "planner.plan.md"))
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", True, description="d",
            declared_outputs=outputs, assets_dir=assets)
        fm_text, _, _ = md[len("---\n"):].partition("\n---\n")
        doc = yaml.safe_load(fm_text)
        tools = doc["tools"]
        self.assertIs(tools["task"], False)
        self.assertIs(tools["*_*"], False)  # MCP catch-all deny
        # The catch-all is server-agnostic: no configured server name ever
        # appears as a key (server names are unknowable at generation time).
        self.assertNotIn("serena", tools)
        # Native tools survive, explicitly re-allowed after the denies.
        keys = list(tools.keys())
        last_deny = max(keys.index(k) for k, v in tools.items() if v is False)
        first_allow = min(keys.index(k) for k, v in tools.items() if v is True)
        self.assertLess(last_deny, first_allow)
        for native in ("read", "edit", "write", "bash", "grep", "glob",
                       "list", "webfetch", "skill", "todowrite", "todoread",
                       "apply_patch"):
            self.assertIs(tools[native], True, native)

    def test_agent_markdown_frontmatter_and_body(self):
        assets = os.path.join(tempfile.mkdtemp(), str(uuid.uuid4()))
        os.makedirs(assets)
        outputs = (os.path.join(assets, "scout-review.json"),)
        md = bridge.opencode_agent_markdown(
            "ROLE PROMPT", "plan", True, description="cowork scout role",
            declared_outputs=outputs, assets_dir=assets)
        self.assertTrue(md.startswith("---\n"))
        self.assertIn("description: cowork scout role", md)
        self.assertIn("mode: primary", md)
        self.assertIn("tools:\n  task: false", md)
        self.assertIn("  edit:", md)
        self.assertNotIn("edit: deny", md)  # no longer the blanket scalar
        for pattern in bridge._opencode_path_patterns(outputs[0], assets):
            self.assertIn(bridge._opencode_yaml_key(pattern), md)
        self.assertTrue(md.rstrip().endswith("ROLE PROMPT"))
        yolo_md = bridge.opencode_agent_markdown(
            "R", "implement", True, description="d")
        self.assertIn("permission:\n  task: deny", yolo_md)

    def test_ensure_opencode_agent_writes_and_regenerates(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE SCOUT")
        name = bridge.ensure_opencode_agent(rp, "scout", "implement", False,
                                            base_dir=base)
        self.assertEqual(name, "cowork-scout")
        path = os.path.join(base, ".opencode", "agents", "cowork-scout.md")
        with open(path) as fh:
            content = fh.read()
        self.assertIn("BE THE SCOUT", content)
        self.assertIn("edit: allow", content)
        # A config change regenerates the file with the new permissions: plan
        # mode now emits the per-file allow map (not the old blanket deny)
        # once an assets dir carrying the role's declared outputs exists.
        assets = tempfile.mkdtemp()
        bridge.ensure_opencode_agent(rp, "scout", "plan", True, base_dir=base,
                                     assets_dir=assets)
        with open(path) as fh:
            regenerated = fh.read()
        self.assertNotIn("edit: allow", regenerated)
        self.assertIn("  edit:", regenerated)
        for out in bridge._declared_outputs_for_role(assets, "scout"):
            for pattern in bridge._opencode_path_patterns(out, assets):
                self.assertIn(bridge._opencode_yaml_key(pattern), regenerated)

    def test_build_opencode_command(self):
        cmd = bridge.build_opencode_command(
            "cowork-scout", "PROMPT", "implement", True,
            model="anthropic/claude-sonnet-4-5", effort="max")
        self.assertEqual(cmd[:4], ["opencode", "run", "--format", "json"])
        self.assertEqual(cmd[cmd.index("--agent") + 1], "cowork-scout")
        self.assertEqual(cmd[cmd.index("--model") + 1],
                         "anthropic/claude-sonnet-4-5")
        self.assertEqual(cmd[cmd.index("--variant") + 1], "max")
        self.assertIn("--auto", cmd)
        self.assertEqual(cmd[-1], "PROMPT")
        # no-yolo and plan runs rely on agent permissions, never --auto.
        self.assertNotIn("--auto", bridge.build_opencode_command(
            "a", "P", "implement", False))
        self.assertNotIn("--auto", bridge.build_opencode_command(
            "a", "P", "plan", True))
        # model/effort omitted -> flags omitted (CLI defaults apply).
        bare = bridge.build_opencode_command("a", "P", "implement", True)
        self.assertNotIn("--model", bare)
        self.assertNotIn("--variant", bare)
        res = bridge.build_opencode_command(
            "a", "P", "implement", True, resume_session_id="ses_1")
        self.assertEqual(res[res.index("--session") + 1], "ses_1")
        self.assertEqual(res[-1], "P")

    def test_parse_opencode_events(self):
        self.assertEqual(
            bridge.parse_opencode_event(
                {"type": "text", "part": {"text": "hi"}}),
            {"kind": "message", "text": "hi"})
        self.assertEqual(
            bridge.parse_opencode_event(
                {"type": "tool", "part": {"tool": "bash"}}),
            {"kind": "tool", "label": "using bash"})
        done = bridge.parse_opencode_event(
            {"type": "tool_use",
             "part": {"tool": "bash", "state": {"status": "completed"}}})
        self.assertEqual(done["kind"], "tool_done")
        denied = bridge.parse_opencode_event(
            {"type": "tool_use",
             "part": {"state": {"status": "error",
                                "error": "The user rejected permission to use "
                                         "this specific tool call."}}})
        self.assertEqual(denied["kind"], "denied")
        err = bridge.parse_opencode_event(
            {"type": "error",
             "error": {"name": "APIError", "data": {"message": "boom"}}})
        self.assertEqual(err, {"kind": "error", "text": "boom"})
        fin = bridge.parse_opencode_event(
            {"type": "step_finish",
             "part": {"reason": "stop", "tokens": {"input": 5}}})
        self.assertEqual(fin["kind"], "step_finish")
        self.assertEqual(fin["reason"], "stop")
        other = bridge.parse_opencode_event({"type": "step_start", "part": {}})
        self.assertEqual(other["kind"], "other")

    def test_capture_session_id_and_usage(self):
        events = [
            {"type": "step_start", "sessionID": "ses_A", "part": {}},
            {"type": "step_finish", "sessionID": "ses_A",
             "part": {"reason": "tool-calls",
                      "tokens": {"input": 10, "output": 2, "reasoning": 3,
                                 "cache": {"read": 7, "write": 1}}}},
            {"type": "step_finish", "sessionID": "ses_A",
             "part": {"reason": "stop", "tokens": {"input": 4, "output": 5}}},
        ]
        self.assertEqual(bridge.capture_opencode_session_id(events), "ses_A")
        self.assertEqual(bridge.opencode_usage(events), {
            "input_tokens": 14, "output_tokens": 10,
            "cache_read_input_tokens": 7, "cache_creation_input_tokens": 1})
        self.assertIsNone(bridge.opencode_usage([{"type": "text", "part": {}}]))
        self.assertIsNone(bridge.capture_opencode_session_id(
            [{"type": "text", "part": {}}]))


class OpencodeArtifactContractTest(unittest.TestCase):
    """Plan-mode setup-time refusal for an unexpressible artifact contract."""

    def test_no_assets_dir_raises_before_any_subprocess_or_file(self):
        import unittest.mock as mock
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")

        def fail_popen(*a, **kw):
            raise AssertionError("subprocess.Popen must not be called")

        with mock.patch.object(
                bridge.subprocess, "Popen", side_effect=fail_popen):
            with self.assertRaises(
                    bridge.OpencodeArtifactContractUnexpressible) as ctx:
                bridge.ensure_opencode_agent(
                    rp, "planner", "plan", True, base_dir=base)
        msg = str(ctx.exception)
        self.assertIn("planner", msg)
        self.assertIn("opencode", msg)
        self.assertIn("plan", msg)
        self.assertIn("planner.plan.json", msg)
        self.assertIn("planner.plan.md", msg)
        path = os.path.join(base, ".opencode", "agents", "cowork-planner.md")
        self.assertFalse(os.path.exists(path))

    def test_outputs_outside_assets_dir_raises(self):
        import unittest.mock as mock
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")
        assets = tempfile.mkdtemp()
        outside = tempfile.mkdtemp()
        with mock.patch.object(
                bridge, "_declared_outputs_for_role",
                return_value=(os.path.join(outside, "planner.plan.json"),)):
            with self.assertRaises(
                    bridge.OpencodeArtifactContractUnexpressible):
                bridge.ensure_opencode_agent(
                    rp, "planner", "plan", True, base_dir=base,
                    assets_dir=assets)
        path = os.path.join(base, ".opencode", "agents", "cowork-planner.md")
        self.assertFalse(os.path.exists(path))

    def test_implement_mode_with_no_assets_dir_is_not_refused(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("BE THE PLANNER")
        name = bridge.ensure_opencode_agent(
            rp, "planner", "implement", False, base_dir=base)
        self.assertEqual(name, "cowork-planner")

    def test_codex_and_claude_plan_paths_not_gated(self):
        # Scoping is structural (P3): only the opencode path ever calls
        # opencode_plan_declared_outputs / raises the new exception, so a
        # Codex or Claude role can never be blocked by it.
        import inspect
        claude_src = inspect.getsource(bridge.ClaudeSession.__init__)
        codex_src = inspect.getsource(bridge.CodexSession.__init__)
        for src in (claude_src, codex_src):
            self.assertNotIn("opencode_plan_declared_outputs", src)
            self.assertNotIn("OpencodeArtifactContractUnexpressible", src)


class OpencodeSessionTest(unittest.TestCase):
    """OpencodeSession turn behavior via a fake subprocess (no real CLI)."""

    def setUp(self):
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    class FakeProc:
        def __init__(self, lines):
            self.stdout = iter(lines)

        def poll(self):
            return 0

        def wait(self, timeout=None):
            return 0

        def terminate(self):
            pass

        def kill(self):
            pass

    def _session(self, tmp, **kw):
        rp = os.path.join(tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        return bridge.OpencodeSession(rp, "implement", True,
                                      agent_base_dir=tmp, **kw)

    def test_fresh_send_captures_session_and_resumes(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()
        lines = [
            json.dumps({"type": "text", "sessionID": "ses_X",
                        "part": {"text": "hello there"}}),
            json.dumps({"type": "step_finish", "sessionID": "ses_X",
                        "part": {"reason": "stop",
                                 "tokens": {"input": 1, "output": 2}}}),
        ]
        got = {}
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return self.FakeProc(lines)

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(tmp, io_out=out,
                              on_session_id=lambda i: got.setdefault("id", i))
            r1 = s.send("first")
            r2 = s.send("second")
        self.assertEqual(s.controller, "opencode")
        self.assertTrue(r1["ok"])
        self.assertTrue(r2["ok"])
        self.assertEqual(got.get("id"), "ses_X")
        self.assertEqual(r1["session_id"], "ses_X")
        # fresh turn has no --session; the follow-up resumes the captured id.
        self.assertNotIn("--session", cmds[0])
        self.assertEqual(cmds[1][cmds[1].index("--session") + 1], "ses_X")
        # both turns target the generated agent.
        for cmd in cmds:
            self.assertEqual(cmd[cmd.index("--agent") + 1], "cowork-scout")
        self.assertIn("hello there", out.getvalue())

    def test_constructor_resume_uses_session_flag(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()
        lines = [json.dumps({"type": "text", "sessionID": "ses_R",
                             "part": {"text": "resumed"}})]
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return self.FakeProc(lines)

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(tmp, io_out=io.StringIO(),
                              resume_session_id="ses_R")
            r = s.send("continue")
        self.assertTrue(r["ok"])
        self.assertEqual(cmds[0][cmds[0].index("--session") + 1], "ses_R")

    def test_denied_error_and_empty_stream(self):
        import tempfile
        import unittest.mock as mock
        tmp = tempfile.mkdtemp()

        def run_with(lines):
            with mock.patch.object(bridge.subprocess, "Popen",
                                   return_value=self.FakeProc(lines)):
                out = io.StringIO()
                s = self._session(tmp, io_out=out)
                return s.send("go"), out.getvalue()

        denied, text = run_with([json.dumps(
            {"type": "tool_use", "sessionID": "ses_D",
             "part": {"state": {"status": "error",
                                "error": "The user rejected permission to use "
                                         "this specific tool call."}}})])
        self.assertFalse(denied["ok"])
        self.assertEqual(denied["result"], "denied")
        self.assertIn("denied", text)

        err, text = run_with([json.dumps(
            {"type": "error", "sessionID": "ses_E",
             "error": {"name": "APIError", "data": {"message": "boom"}}})])
        self.assertFalse(err["ok"])
        self.assertEqual(err["result"], "error")
        self.assertIn("boom", text)

        empty, _ = run_with([])
        self.assertFalse(empty["ok"])
        self.assertEqual(empty.get("error_type"), "no_events")


class OpencodeDeliveryFallbackTest(unittest.TestCase):
    """ORCH-052: an `opencode run --agent` that dies pre-model because the
    project-local agent file could not be loaded is retried exactly once via
    the global config dir; ordinary provider errors never trigger this."""

    DELIVERY_ERROR = json.dumps(
        {"type": "error",
         "error": {"name": "UnknownError",
                   "data": {"message": "Unexpected server error"}}})
    OK_LINES = [
        json.dumps({"type": "text", "sessionID": "ses_F",
                    "part": {"text": "rescued"}}),
        json.dumps({"type": "step_finish", "sessionID": "ses_F",
                    "part": {"reason": "stop",
                             "tokens": {"input": 1, "output": 1}}}),
    ]

    def setUp(self):
        import tempfile
        self.tmp = tempfile.mkdtemp()
        self.config = tempfile.mkdtemp()
        self._env = os.environ.get("OPENCODE_CONFIG_DIR")
        os.environ["OPENCODE_CONFIG_DIR"] = self.config
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def tearDown(self):
        if self._env is None:
            os.environ.pop("OPENCODE_CONFIG_DIR", None)
        else:
            os.environ["OPENCODE_CONFIG_DIR"] = self._env
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def _session(self, **kw):
        rp = os.path.join(self.tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        return bridge.OpencodeSession(rp, "implement", True,
                                      agent_base_dir=self.tmp, **kw)

    def _global_files(self):
        import glob as globmod
        return sorted(globmod.glob(
            os.path.join(self.config, "agent", "*.md")))

    def test_delivery_failure_falls_back_to_global_agent(self):
        import unittest.mock as mock
        cmds = []
        snapshots = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            files = self._global_files()
            snapshots.append(
                {f: open(f).read() for f in files})
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=out)
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 2)
        self.assertEqual(r["session_id"], "ses_F")
        # first attempt targeted the project-local agent, no global file yet.
        self.assertEqual(cmds[0][cmds[0].index("--agent") + 1], "cowork-scout")
        self.assertEqual(snapshots[0], {})
        # retry targeted a session-scoped global agent whose content matches
        # the project-local file byte for byte.
        global_agent = cmds[1][cmds[1].index("--agent") + 1]
        self.assertTrue(global_agent.startswith("cowork-scout-"))
        local = open(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")).read()
        self.assertEqual(list(snapshots[1].values()), [local])
        self.assertIn(global_agent + ".md",
                      os.path.basename(list(snapshots[1])[0]))
        # ORCH-001: the global fallback copy inherits the MCP-disable tools
        # block (it re-reads the local file byte for byte).
        self.assertIn(OpencodeBridgeTest.TOOLS_BLOCK, local)
        self.assertIn('"*_*": false', list(snapshots[1].values())[0])
        # the global file is removed as soon as the run exits; sticky flag set.
        self.assertEqual(self._global_files(), [])
        self.assertTrue(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_fallback_failure_reports_agent_delivery_failed(self):
        import unittest.mock as mock
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])

        out = io.StringIO()
        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=out)
            r = s.send("go")
        self.assertFalse(r["ok"])
        self.assertEqual(r.get("error_type"), "agent_delivery_failed")
        self.assertEqual(len(cmds), 2)  # one retry, never a loop
        text = out.getvalue()
        self.assertIn("cowork-scout.md", text)
        self.assertIn(os.path.join(self.config, "agent"), text)
        self.assertEqual(self._global_files(), [])
        self.assertFalse(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_ordinary_error_does_not_fallback(self):
        import unittest.mock as mock
        for lines in (
            # different error text: ordinary provider error.
            [json.dumps({"type": "error",
                         "error": {"name": "APIError",
                                   "data": {"message": "boom"}}})],
            # delivery-shaped error AFTER real output: not a delivery failure.
            [json.dumps({"type": "text", "sessionID": "ses_X",
                         "part": {"text": "partial"}}),
             self.DELIVERY_ERROR],
        ):
            cmds = []

            def fake_popen(command, **kwargs):
                cmds.append(command)
                return OpencodeSessionTest.FakeProc(list(lines))

            with mock.patch.object(bridge.subprocess, "Popen",
                                   side_effect=fake_popen):
                s = self._session(io_out=io.StringIO())
                r = s.send("go")
            self.assertFalse(r["ok"])
            self.assertNotEqual(r.get("error_type"), "agent_delivery_failed")
            self.assertEqual(len(cmds), 1)
            self.assertEqual(self._global_files(), [])
            self.assertFalse(bridge._OPENCODE_GLOBAL_DELIVERY)

    def test_delivery_failure_ignores_failed_attempt_session_id(self):
        import unittest.mock as mock
        bad = json.dumps(
            {"type": "error", "sessionID": "ses_BAD",
             "error": {"name": "UnknownError",
                       "data": {"message": "Unexpected server error"}}})
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([bad])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=io.StringIO())
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertNotIn("--session", cmds[1])
        self.assertEqual(r["session_id"], "ses_F")

    def test_sticky_module_flag_skips_local_attempt(self):
        import unittest.mock as mock
        bridge._OPENCODE_GLOBAL_DELIVERY = True
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        with mock.patch.object(bridge.subprocess, "Popen",
                               side_effect=fake_popen):
            s = self._session(io_out=io.StringIO())
            r = s.send("go")
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 1)
        agent = cmds[0][cmds[0].index("--agent") + 1]
        self.assertTrue(agent.startswith("cowork-scout-"))
        # the project-local file is still written (overwrite-per-spawn
        # contract unchanged) and the global copy leaves no residue.
        self.assertTrue(os.path.exists(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")))
        self.assertEqual(self._global_files(), [])

    def test_global_agent_dir_env_and_default(self):
        self.assertEqual(bridge.opencode_global_agent_dir(),
                         os.path.join(self.config, "agent"))
        os.environ.pop("OPENCODE_CONFIG_DIR", None)
        self.assertEqual(
            bridge.opencode_global_agent_dir(),
            os.path.join(os.path.expanduser("~"), ".config", "opencode",
                         "agent"))

    def test_write_opencode_global_agent(self):
        name, path = bridge.write_opencode_global_agent(
            "CONTENT\n", "planner", "abc12345")
        self.assertEqual(name, "cowork-planner-abc12345")
        self.assertEqual(
            path, os.path.join(self.config, "agent", name + ".md"))
        self.assertEqual(open(path).read(), "CONTENT\n")


class McpFreeLaunchTests(unittest.TestCase):
    """ORCH-001: every cowork role launches MCP-free on every controller —
    claude, codex, opencode — fresh and resumed, guarded and unguarded."""

    def _assert_claude_mcp_free(self, cmd):
        i = cmd.index("--mcp-config")
        self.assertEqual(cmd[i + 1], bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH)
        self.assertTrue(os.path.isabs(cmd[i + 1]))
        self.assertEqual(cmd[i + 2], "--strict-mcp-config")

    def test_claude_fresh_resume_and_probe_forms_carry_mcp_flags(self):
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                fresh = bridge.build_claude_command(
                    "roles/scout.md", mode, yolo,
                    session_id=str(uuid.uuid4()))
                self._assert_claude_mcp_free(fresh)
                resumed = bridge.build_claude_command(
                    "roles/scout.md", mode, yolo,
                    resume_id=str(uuid.uuid4()))
                self._assert_claude_mcp_free(resumed)
        # The probe's argument shapes: unguarded (no session/guard dir) and
        # guarded (settings path + delegation lockdown).
        probe_unguarded = bridge.build_claude_command(
            "roles/scout.md", "plan", True,
            extra_writable_dir=tempfile.mkdtemp())
        self._assert_claude_mcp_free(probe_unguarded)
        probe_guarded = bridge.build_claude_command(
            "roles/scout.md", "plan", True,
            guard_settings_path="/x/settings.json",
            delegation_allowed=False, session_id=str(uuid.uuid4()))
        self._assert_claude_mcp_free(probe_guarded)

    def test_claude_empty_mcp_config_is_a_committed_empty_server_map(self):
        # The static file the flag pair points at really is an empty,
        # valid MCP config — no servers, ever.
        self.assertTrue(os.path.isfile(bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH))
        with open(bridge.CLAUDE_EMPTY_MCP_CONFIG_PATH) as fh:
            self.assertEqual(json.load(fh), {"mcpServers": {}})

    def _assert_codex_mcp_free(self, cmd):
        values = [cmd[i + 1] for i, part in enumerate(cmd)
                  if part == "-c" and i + 1 < len(cmd)]
        self.assertIn("mcp_servers={}", values)
        # The user-config load is disabled exactly once — by governance args
        # on the guarded path, by the MCP override helper on the unguarded
        # one (see codex_mcp_override_args).
        self.assertEqual(cmd.count("--ignore-user-config"), 1)

    def test_codex_fresh_and_resume_carry_mcp_override(self):
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                for guarded in (False, True):
                    fresh = bridge.build_codex_command(
                        "PROMPT", mode, yolo, guarded=guarded)
                    self._assert_codex_mcp_free(fresh)
                    resumed = bridge.build_codex_resume_command(
                        "T1", "PROMPT", mode, yolo, guarded=guarded)
                    self._assert_codex_mcp_free(resumed)

    def test_opencode_agent_markdown_carries_mcp_deny_all_modes(self):
        block = OpencodeBridgeTest.TOOLS_BLOCK
        for mode in ("plan", "implement"):
            for yolo in (True, False):
                md = bridge.opencode_agent_markdown(
                    "R", mode, yolo, description="d")
                self.assertIn(block, md)
                # Deny-first: the MCP catch-all precedes every re-allow.
                self.assertLess(md.index('"*_*": false'),
                                md.index("  read: true"))

    def test_opencode_project_local_agent_file_carries_mcp_deny(self):
        base = tempfile.mkdtemp()
        rp = os.path.join(base, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        name = bridge.ensure_opencode_agent(rp, "scout", "implement", True,
                                            base_dir=base)
        with open(os.path.join(base, ".opencode", "agents",
                               name + ".md")) as fh:
            content = fh.read()
        self.assertIn(OpencodeBridgeTest.TOOLS_BLOCK, content)

    def test_no_role_prompt_mentions_mcp(self):
        # Requirement 4 as a regression test: no cowork role prompt mentions
        # MCP (case-insensitively), so reintroduction fails the suite.
        roles_dir = os.path.join(_HERE, os.pardir, "roles")
        role_files = sorted(
            os.path.join(roles_dir, f) for f in os.listdir(roles_dir)
            if f.endswith(".md"))
        self.assertEqual(len(role_files), 8)
        for path in role_files:
            with open(path) as fh:
                self.assertNotIn("mcp", fh.read().lower(), path)


class McpFreeTraceMarkerTests(unittest.TestCase):
    """ORCH-001: every launch is auditable as MCP-free from the trace alone —
    `controller.turn.start` (all three controllers) and `controller.probe.start`
    (claude) carry `mcp_free=True` + the mechanism, and no event leaks MCP
    server names, tool schemas, or credentials."""

    def _tmp_trace(self):
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return os.path.join(d, "trace.jsonl")

    def _events(self, path):
        with open(path, "r") as fh:
            return [json.loads(line) for line in fh if line.strip()]

    def _assert_marker(self, event, mechanism):
        self.assertIs(event["mcp_free"], True)
        self.assertEqual(event["mcp_mechanism"], mechanism)
        # No MCP server names, tool schemas, or credentials anywhere in the
        # event payload.
        payload = json.dumps(event)
        self.assertNotIn("mcp__", payload)
        self.assertNotIn("mcpServers", payload)

    def test_claude_probe_start_trace_carries_mcp_free_marker(self):
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")

        def spawn(cmd, stdin):
            return [{"type": "result", "subtype": "success"}]
        ok, _ = bridge.probe_claude_stream_json(spawn, trace=trace)
        self.assertTrue(ok)
        start = [e for e in self._events(path)
                 if e["event"] == "controller.probe.start"][0]
        self._assert_marker(start, "claude_empty_mcp_config")

    def test_claude_turn_start_trace_carries_mcp_free_marker(self):
        import unittest.mock as mock
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")
        lines = [
            json.dumps({"type": "assistant", "message": {
                "content": [{"type": "text", "text": "hi"}]}}),
            json.dumps({"type": "result", "subtype": "success",
                        "session_id": "S1"}),
        ]
        with mock.patch.object(bridge.subprocess, "Popen",
                               return_value=_ClaudeProc(lines)):
            session = bridge.ClaudeSession(
                "roles/scout.md", "plan", True, io_out=io.StringIO(),
                speaker="scout", trace=trace)
            session.send("fresh turn", meta={"fresh": True})
            session.send("resumed turn", meta={"fresh": False, "resume": True})
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "claude_empty_mcp_config")

    def test_codex_turn_start_trace_carries_mcp_free_marker(self):
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")

        class FakeCodex(bridge.CodexSession):
            def _run(self, command):
                return [{"type": "thread.started", "thread_id": "T1"}]

        session = FakeCodex("implement", True, io_out=io.StringIO(),
                            trace=trace)
        session.send("fresh turn")
        session.send("resumed turn")
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "codex_mcp_override")

    def test_opencode_turn_start_trace_carries_mcp_free_marker(self):
        import unittest.mock as mock
        path = self._tmp_trace()
        trace = trace_store.Trace(path, session_uuid="X", run_id="R")
        lines = [
            json.dumps({"type": "text", "sessionID": "ses_M",
                        "part": {"text": "hi"}}),
            json.dumps({"type": "step_finish", "sessionID": "ses_M",
                        "part": {"reason": "stop",
                                 "tokens": {"input": 1, "output": 1}}}),
        ]
        tmp = tempfile.mkdtemp()
        rp = os.path.join(tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        with mock.patch.object(
                bridge.subprocess, "Popen",
                return_value=OpencodeSessionTest.FakeProc(lines)):
            session = bridge.OpencodeSession(
                rp, "implement", True, io_out=io.StringIO(),
                agent_base_dir=tmp, trace=trace)
            session.send("fresh turn")
            session.send("resumed turn")
        starts = [e for e in self._events(path)
                  if e["event"] == "controller.turn.start"]
        self.assertEqual(len(starts), 2)
        self.assertTrue(starts[0]["fresh"])
        self.assertTrue(starts[1]["resume"])
        for event in starts:
            self._assert_marker(event, "opencode_tools_deny")


class OpencodeReadonlyBashTest(unittest.TestCase):
    """ORCH-053: the read-only bash allowlist derives from the vetted
    action-policy tables and is emitted only when explicitly requested."""

    def test_readonly_bash_patterns_derive_from_policy_tables(self):
        commands = action_policy.readonly_bash_commands()
        expected = tuple(
            "git %s" % sub for sub in action_policy.SAFE_GIT_FLAGS) + tuple(
            sorted(action_policy.INERT_COMMANDS - {"git"}))
        self.assertEqual(commands, expected)
        patterns = action_policy.readonly_bash_glob_patterns()
        for cmd in commands:
            self.assertIn(cmd, patterns)
            self.assertIn(cmd + " *", patterns)
        self.assertEqual(len(patterns), 2 * len(commands))
        # nothing from the mutating table may ever appear.
        heads = {p.split(" ", 1)[0] for p in patterns}
        self.assertFalse(heads & set(action_policy.MUTATING_COMMANDS))

    def _bash_block(self, lines):
        idx = lines.index("  bash:")
        end = lines.index("  webfetch: allow")
        return lines[idx + 1:end]

    def test_permission_lines_bash_readonly_map_fallback_branch(self):
        lines = bridge.opencode_permission_lines(
            "plan", False, bash_readonly=True)
        self.assertNotIn("  bash: ask", lines)
        block = self._bash_block(lines)
        self.assertEqual(
            block[0], "    %s: ask" % bridge._opencode_yaml_key("*"))
        self.assertEqual(
            block[1:],
            ["    %s: allow" % bridge._opencode_yaml_key(p)
             for p in action_policy.readonly_bash_glob_patterns()])
        self.assertIn('    "git status *": allow', block)

    def test_permission_lines_bash_readonly_map_declared_outputs_branch(self):
        import tempfile
        assets = tempfile.mkdtemp()
        out = os.path.join(assets, "scout.intel.json")
        lines = bridge.opencode_permission_lines(
            "plan", False, declared_outputs=(out,), assets_dir=assets,
            bash_readonly=True)
        self.assertNotIn("  bash: ask", lines)
        block = self._bash_block(lines)
        self.assertEqual(
            block[0], "    %s: ask" % bridge._opencode_yaml_key("*"))
        self.assertIn('    "git status *": allow', block)

    def test_bash_readonly_off_and_yolo_implement_unchanged(self):
        self.assertIn("  bash: ask",
                      bridge.opencode_permission_lines("plan", False))
        self.assertIn("  bash: ask",
                      bridge.opencode_permission_lines("implement", False))
        self.assertEqual(
            bridge.opencode_permission_lines(
                "implement", True, bash_readonly=True),
            ["permission:", "  task: deny"])

    def test_opencode_data_dir_honors_xdg(self):
        self.assertEqual(
            controller_profiles.opencode_data_dir(
                environ={"XDG_DATA_HOME": "/x/data"}),
            os.path.join("/x/data", "opencode"))
        self.assertEqual(
            controller_profiles.opencode_data_dir(environ={}, home="/h"),
            os.path.join("/h", ".local", "share", "opencode"))

    def test_capability_matrix_marks_opencode_opportunistic(self):
        for mode in ("plan", "implement"):
            row = action_policy.CONTROLLER_CAPABILITY_MATRIX[
                ("opencode", mode)]
            self.assertEqual(row["kernel_boundary"], "opportunistic")
            self.assertEqual(row["mutation_gate"], "controller_permissions")

    def test_build_command_pins_directory(self):
        cmd = bridge.build_opencode_command(
            "cowork-scout", "hi", "plan", False, directory="/w/tree")
        self.assertEqual(cmd[cmd.index("--dir") + 1], "/w/tree")
        self.assertNotIn(
            "--dir", bridge.build_opencode_command(
                "cowork-scout", "hi", "plan", False))

    def test_bash_readonly_appends_shell_guidance_to_body(self):
        md = bridge.opencode_agent_markdown(
            "ROLE", "plan", False, description="d", bash_readonly=True)
        self.assertIn("READ-ONLY", md)
        self.assertIn("use the write/edit tools", md)
        base = bridge.opencode_agent_markdown(
            "ROLE", "plan", False, description="d")
        self.assertNotIn("READ-ONLY", base)
        self.assertTrue(base.endswith("ROLE\n"))


class OpencodeSeatbeltWrapTest(unittest.TestCase):
    """ORCH-053: a guarded OpencodeSession wraps every argv it builds in the
    kernel write boundary — the fresh turn and the ORCH-052 fallback retry
    alike — and passes the guard env to the child."""

    DELIVERY_ERROR = OpencodeDeliveryFallbackTest.DELIVERY_ERROR
    OK_LINES = OpencodeDeliveryFallbackTest.OK_LINES

    def setUp(self):
        import tempfile
        self.tmp = tempfile.mkdtemp()
        self.config = tempfile.mkdtemp()
        self._env = os.environ.get("OPENCODE_CONFIG_DIR")
        os.environ["OPENCODE_CONFIG_DIR"] = self.config
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def tearDown(self):
        if self._env is None:
            os.environ.pop("OPENCODE_CONFIG_DIR", None)
        else:
            os.environ["OPENCODE_CONFIG_DIR"] = self._env
        bridge._OPENCODE_GLOBAL_DELIVERY = False

    def _run_guarded(self, popen_side_effect):
        import unittest.mock as mock
        rp = os.path.join(self.tmp, "role.md")
        with open(rp, "w") as fh:
            fh.write("ROLE")
        scope = action_policy.OwnedScope(session_assets_dir=self.tmp)
        runtime = {"scope": scope, "env": {"TMPDIR": self.tmp},
                   "protected_paths": (), "broker": None, "profile": None}

        def fake_boundary(owned_scope, argv=None, protected_paths=(),
                          claude_cwd_tracker=False):
            return {"available": True, "platform": "darwin",
                    "profile": "", "argv": ["sandbox-exec"] + list(argv)}

        with mock.patch.object(bridge, "nested_guard_active",
                               return_value=True), \
                mock.patch.object(bridge.sys, "platform", "darwin"), \
                mock.patch.object(bridge.shutil, "which",
                                  return_value="/usr/bin/sandbox-exec"), \
                mock.patch.object(bridge, "_guard_runtime",
                                  return_value=runtime), \
                mock.patch.object(bridge, "kernel_write_boundary",
                                  side_effect=fake_boundary), \
                mock.patch.object(bridge.subprocess, "Popen",
                                  side_effect=popen_side_effect):
            s = bridge.OpencodeSession(rp, "plan", False, io_out=io.StringIO(),
                                       agent_base_dir=self.tmp,
                                       extra_writable_dir=self.tmp)
            return s.send("go")

    def test_fresh_turn_wrapped_and_env_passed(self):
        cmds, envs = [], []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            envs.append(kwargs.get("env"))
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        r = self._run_guarded(fake_popen)
        self.assertTrue(r["ok"])
        self.assertEqual(cmds[0][0], "sandbox-exec")
        self.assertEqual(envs[0], {"TMPDIR": self.tmp})
        # the bash allowlist rode along in the generated frontmatter.
        agent = open(os.path.join(
            self.tmp, ".opencode", "agents", "cowork-scout.md")).read()
        self.assertIn('"git status *": allow', agent)
        self.assertIn('"*": ask', agent)

    def test_fallback_retry_also_wrapped(self):
        cmds = []

        def fake_popen(command, **kwargs):
            cmds.append(command)
            if len(cmds) == 1:
                return OpencodeSessionTest.FakeProc([self.DELIVERY_ERROR])
            return OpencodeSessionTest.FakeProc(list(self.OK_LINES))

        r = self._run_guarded(fake_popen)
        self.assertTrue(r["ok"])
        self.assertEqual(len(cmds), 2)
        for cmd in cmds:
            self.assertEqual(cmd[0], "sandbox-exec")


class PreflightTest(unittest.TestCase):
    def test_python_floor(self):
        ok, alert = preflight.check_python((3, 9, 6))
        self.assertTrue(ok)
        self.assertIsNone(alert)
        ok, alert = preflight.check_python((3, 8, 18))
        self.assertFalse(ok)
        self.assertIn("3.8.18", alert)

    def test_required_controllers_dedup(self):
        cfg = {
            "scout": {"controller": "claude"},
            "planner": {"controller": "claude"},
            "planning-advisor": {"controller": "codex"},
        }
        self.assertEqual(preflight.required_controllers(cfg), ["claude", "codex"])

    def test_check_controllers_missing_and_present(self):
        ok, alerts = preflight.check_controllers(["claude"], which=lambda c: None)
        self.assertFalse(ok)
        self.assertIn("@anthropic-ai/claude-code", alerts[0])

        ok, alerts = preflight.check_controllers(["codex"], which=lambda c: None)
        self.assertIn("@openai/codex", alerts[0])

        ok, alerts = preflight.check_controllers(
            ["claude"], which=lambda c: "/usr/bin/" + c
        )
        self.assertTrue(ok)
        self.assertEqual(alerts, [])

    def test_preflight_aggregates_alerts(self):
        cfg = {"scout": {"controller": "codex"}}
        ok, alerts = preflight.preflight(
            cfg, version_info=(3, 8, 0), which=lambda c: None
        )
        self.assertFalse(ok)
        # python alert + codex alert
        self.assertEqual(len(alerts), 2)

class ConfigTest(unittest.TestCase):
    def test_default_config_matches_defaults(self):
        cfg = cowork.default_config(cowork.ROLES)
        # Roles default to implement mode (guardrailed by role spec, not plan)
        # and to the controller CLI's own model/effort (None).
        self.assertEqual(cfg["scout"],
                         {"controller": "claude", "model": None, "effort": None,
                          "yolo": True, "mode": "implement"})
        for role in cowork.ROLES:
            self.assertEqual(cfg[role]["mode"], "implement")
            self.assertIsNone(cfg[role]["model"])
            self.assertIsNone(cfg[role]["effort"])

    def test_apply_config_override(self):
        cfg = cowork.default_config(["scout"])
        ok, err = cowork.apply_config_override(
            cfg, "scout", ["codex", "no-yolo", "implement"])
        self.assertTrue(ok)
        self.assertEqual(
            cfg["scout"], {"controller": "codex", "model": None, "effort": None,
                           "yolo": False, "mode": "implement"})
        ok, _ = cowork.apply_config_override(cfg, "ghost", ["claude"])
        self.assertFalse(ok)
        ok, _ = cowork.apply_config_override(cfg, "scout", ["bogus"])
        self.assertFalse(ok)

    def test_apply_config_override_opencode_model_effort(self):
        cfg = cowork.default_config(["scout"])
        ok, err = cowork.apply_config_override(
            cfg, "scout", ["opencode", "model=openai/gpt-5.4", "effort=high"])
        self.assertTrue(ok)
        self.assertEqual(cfg["scout"]["controller"], "opencode")
        self.assertEqual(cfg["scout"]["model"], "openai/gpt-5.4")
        self.assertEqual(cfg["scout"]["effort"], "high")
        # model=default / effort=default reset to the CLI's own setting.
        ok, _ = cowork.apply_config_override(
            cfg, "scout", ["model=default", "effort=default"])
        self.assertTrue(ok)
        self.assertIsNone(cfg["scout"]["model"])
        self.assertIsNone(cfg["scout"]["effort"])
        ok, _ = cowork.apply_config_override(cfg, "scout", ["speed=fast"])
        self.assertFalse(ok)

    def test_normalize_role_config_backfills_model_effort(self):
        old = {"controller": "codex", "yolo": True, "mode": "implement"}
        normalized = cowork.normalize_role_config(old)
        self.assertEqual(normalized,
                         {"controller": "codex", "model": None, "effort": None,
                          "yolo": True, "mode": "implement"})
        self.assertNotIn("model", old)  # input never mutated


class ArgsPathTest(unittest.TestCase):
    def _args(self, argv):
        return cowork.build_parser().parse_args(argv)

    def test_parse_team(self):
        selected, err = cowork.parse_team("planning-advisor,scout")
        self.assertIsNone(err)
        self.assertEqual(selected, ["scout", "planning-advisor"])  # canonical order
        selected, err = cowork.parse_team("scout,ghost")
        self.assertIsNotNone(err)
        # the reserved name was renamed: plain `advisor` is no longer a role
        selected, err = cowork.parse_team("scout,advisor")
        self.assertIsNotNone(err)

    def test_apply_config_args(self):
        cfg = cowork.default_config(["scout", "planning-advisor"])
        ok, err = cowork.apply_config_args(cfg, ["scout=codex,no-yolo,implement"])
        self.assertTrue(ok)
        self.assertEqual(
            cfg["scout"], {"controller": "codex", "model": None, "effort": None,
                           "yolo": False, "mode": "implement"})
        ok, err = cowork.apply_config_args(cfg, ["scoutcodex"])  # no '='
        self.assertFalse(ok)
        # key=value options ride in the same comma list; ROLE= splits on the
        # FIRST '=' only, so model=/effort= survive intact.
        ok, err = cowork.apply_config_args(
            cfg, ["scout=opencode,model=anthropic/claude-sonnet-4-5,"
                  "effort=max,yolo"])
        self.assertTrue(ok)
        self.assertEqual(
            cfg["scout"],
            {"controller": "opencode", "model": "anthropic/claude-sonnet-4-5",
             "effort": "max", "yolo": True, "mode": "implement"})

    def test_resolve_context_text_and_file(self):
        args = self._args(["--context", "hello"])
        self.assertEqual(cowork.resolve_context(args), "hello")
        import tempfile
        with tempfile.NamedTemporaryFile("w", suffix=".txt", delete=False) as fh:
            fh.write("from file")
            path = fh.name
        try:
            args = self._args(["--context-file", path])
            self.assertEqual(cowork.resolve_context(args), "from file")
        finally:
            os.unlink(path)

    def test_resolve_context_absent_is_empty_and_reads_no_stdin(self):
        # No context argument => "" (a resume auto-continues with "Continue the
        # session."); nothing is ever read from stdin.
        import unittest.mock as mock
        with mock.patch.object(sys, "stdin", mock.Mock(
                read=mock.Mock(side_effect=AssertionError("read stdin")))):
            self.assertEqual(cowork.resolve_context(self._args([])), "")
            self.assertEqual(
                cowork.resolve_context(self._args([]), resuming=True), "")
        # An explicit --context still wins on resume (redirect a resumed session).
        self.assertEqual(
            cowork.resolve_context(self._args(["--context", "new goal"]),
                                   resuming=True),
            "new goal")

    def test_run_flow_reaches_scout(self):
        captured = {}

        def fake_run_scout(config, context, selected, io_out=None,
                           resume_id=None, on_session=None, intel_path=None,
                           review_path=None, **kwargs):
            captured["config"] = config
            captured["context"] = context
            captured["selected"] = selected
            captured["intel_path"] = intel_path
            captured["review_path"] = review_path
            return 0

        args = self._args(
            ["--team", "scout,scout-reviewer,planning-advisor",
             "--config", "scout=codex,no-yolo,implement",
             "--context", "do the thing", "--no-session"])
        out = io.StringIO()
        rc = cowork.run_flow(
            args, io_out=out,
            which=lambda c: "/bin/" + c,  # everything present
            run_scout_fn=fake_run_scout,
        )
        self.assertEqual(rc, 1)
        self.assertEqual(captured["selected"],
                         ["scout", "scout-reviewer", "planning-advisor"])
        # The fresh scout's seed carries the goal AND the repo-discovery note.
        self.assertIn("do the thing", captured["context"])
        self.assertIn("Repository discovery", captured["context"])
        self.assertEqual(captured["config"]["scout"]["controller"], "codex")

    def test_reviewer_only_team_is_refused_before_dispatch(self):
        # A reviewer-only team (no lead role) starts in the default scouting
        # phase and is refused as scout-not-selected: an invalid invocation.
        args = self._args(
            ["--team", "build-reviewer", "--context", "x", "--no-session"])
        out = io.StringIO()
        box = {}
        rc = cowork.run_flow(
            args, io_out=out, which=lambda c: "/bin/" + c, result_box=box)
        self.assertEqual(rc, 2)
        self.assertEqual(box["reason"], "scout_not_selected")
        self.assertIn("scout not selected", out.getvalue())


class StateStoreTest(unittest.TestCase):
    def _tmp(self):
        import tempfile
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: __import__("shutil").rmtree(d, ignore_errors=True))
        return os.path.join(d, ".cowork", "session.json")

    def test_save_load_roundtrip_and_has_config(self):
        path = self._tmp()
        self.assertIsNone(state_store.load(path))
        cfg = cowork.default_config(["scout", "planning-advisor"])
        state_store.save_config(path, ["scout", "planning-advisor"], cfg)
        loaded = state_store.load(path)
        self.assertTrue(state_store.has_config(loaded))
        self.assertEqual(loaded["team"], ["scout", "planning-advisor"])
        self.assertEqual(loaded["config"]["scout"]["controller"], "claude")

    def test_role_session_roundtrip_and_controller_match(self):
        path = self._tmp()
        state_store.save_config(path, ["scout"], cowork.default_config(["scout"]))
        state_store.save_role_session(path, "scout", "claude", "uuid-123")
        loaded = state_store.load(path)
        self.assertEqual(
            state_store.get_role_session(loaded, "scout", "claude"), "uuid-123")
        # controller mismatch -> no resume id
        self.assertIsNone(
            state_store.get_role_session(loaded, "scout", "codex"))

    def test_switch_role_controller_clears_active_id_and_preserves_bookkeeping(self):
        path = self._tmp()
        state = state_store.save_config(
            path, ["planner"], cowork.default_config(["planner"]))
        state = state_store.save_role_session(
            path, "planner", "claude", "old-claude", prior=state)
        state["sessions"]["planner"]["last_context_revision_seen"] = 7
        state["sessions"]["planner"]["last_approved_baseline"] = {"sha": "abc"}
        state_store.save(path, state)

        switched = state_store.switch_role_controller(
            path, "planner", "codex", prior=state, reason="limit",
            source="gate", created=123.0)

        self.assertEqual(switched["config"]["planner"]["controller"], "codex")
        sess = switched["sessions"]["planner"]
        self.assertEqual(sess["controller"], "codex")
        self.assertNotIn("id", sess)
        self.assertEqual(sess["last_context_revision_seen"], 7)
        self.assertEqual(sess["last_approved_baseline"], {"sha": "abc"})
        self.assertIsNone(
            state_store.get_role_session(switched, "planner", "codex"))
        pending = state_store.read_pending_switch(switched, "planner")
        self.assertEqual(pending["from_controller"], "claude")
        self.assertEqual(pending["to_controller"], "codex")
        self.assertEqual(pending["source"], "gate")

        saved = state_store.save_role_session(
            path, "planner", "codex", "new-thread", prior=switched)
        self.assertEqual(
            state_store.get_role_session(saved, "planner", "codex"),
            "new-thread")
        cleared = state_store.clear_pending_switch(path, "planner", prior=saved)
        self.assertIsNone(state_store.read_pending_switch(cleared, "planner"))

    def test_ensure_session_mints_and_persists_uuid_once(self):
        path = self._tmp()
        s1 = state_store.ensure_session(path, None, "fixed-uuid")
        self.assertEqual(state_store.get_session_uuid(s1), "fixed-uuid")
        self.assertEqual(
            state_store.get_session_uuid(state_store.load(path)), "fixed-uuid")
        # a second call with a different candidate must not overwrite it
        s2 = state_store.ensure_session(path, state_store.load(path), "other")
        self.assertEqual(state_store.get_session_uuid(s2), "fixed-uuid")

    def test_read_status(self):
        path = self._tmp()
        self.assertIsNone(state_store.read_status(path))  # missing
        os.makedirs(os.path.dirname(path))
        with open(path, "w") as fh:
            fh.write('{"session":"x","role":"scout","status":"needs_input","result":{}}')
        self.assertEqual(state_store.read_status(path), "needs_input")
        with open(path, "w") as fh:
            fh.write("not json")
        self.assertIsNone(state_store.read_status(path))

    def test_invalidate_ready_status(self):
        path = self._tmp()
        self.assertFalse(state_store.invalidate_ready_status(path))  # missing
        os.makedirs(os.path.dirname(path))
        with open(path, "w") as fh:
            json.dump({"status": "ready_for_review",
                       "result": {"summary": "keep me"}}, fh)
        self.assertTrue(state_store.invalidate_ready_status(path))
        with open(path, "r") as fh:
            data = json.load(fh)
        self.assertEqual(data["status"], "needs_input")
        self.assertEqual(data["result"], {"summary": "keep me"})
        self.assertFalse(state_store.invalidate_ready_status(path))

    def test_load_rejects_incompatible_version(self):
        path = self._tmp()
        os.makedirs(os.path.dirname(path))
        with open(path, "w") as fh:
            fh.write('{"version": 999, "team": ["scout"], "config": {}}')
        self.assertIsNone(state_store.load(path))

    def test_fingerprint_tolerance_missing(self):
        # T6: a missing/unreadable file yields the all-None/exists:False shape
        # and never raises.
        self.assertEqual(
            state_store.fingerprint_status(None),
            {"exists": False, "status": None, "sha256": None,
             "size": None, "mtime_ns": None})
        path = self._tmp()
        fp = state_store.fingerprint_status(path)  # parent dir does not exist
        self.assertFalse(fp["exists"])
        self.assertIsNone(fp["status"])
        self.assertIsNone(fp["sha256"])
        self.assertIsNone(fp["size"])

    def test_fingerprint_malformed_readable(self):
        # T6b: a present-but-malformed artifact never raises and returns
        # exists:True, status:None, AND a real sha256/size from the raw bytes.
        path = self._tmp()
        os.makedirs(os.path.dirname(path))
        with open(path, "w") as fh:
            fh.write("this is not json {")
        fp = state_store.fingerprint_status(path)
        self.assertTrue(fp["exists"])
        self.assertIsNone(fp["status"])     # unparseable -> no status
        self.assertIsNotNone(fp["sha256"])  # but a real raw-byte hash
        self.assertEqual(fp["size"], len(b"this is not json {"))
        # Two malformed writes with DIFFERENT bytes produce DIFFERENT sha256,
        # so a malformed-but-changed turn reads as progress, not a no-op.
        with open(path, "w") as fh:
            fh.write("still not json }")
        fp2 = state_store.fingerprint_status(path)
        self.assertTrue(fp2["exists"])
        self.assertIsNone(fp2["status"])
        self.assertNotEqual(fp["sha256"], fp2["sha256"])

    def test_fingerprint_wellformed_reports_status(self):
        path = self._tmp()
        os.makedirs(os.path.dirname(path))
        with open(path, "w") as fh:
            json.dump({"status": "ready_for_review", "result": {}}, fh)
        fp = state_store.fingerprint_status(path)
        self.assertTrue(fp["exists"])
        self.assertEqual(fp["status"], "ready_for_review")
        self.assertIsNotNone(fp["sha256"])
        self.assertGreater(fp["size"], 0)


class MultiSessionStoreTest(unittest.TestCase):
    def _dir(self):
        import tempfile
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return d

    def _write_session(self, cwd, suid=None, legacy=False, context=None,
                       phase=None, created=None, mtime=None):
        if legacy:
            path = state_store.session_path(cwd)
        else:
            path = state_store.new_session_path(cwd, suid)
        state = {"team": [], "config": {}, "sessions": {}}
        if suid:
            state["session_uuid"] = suid
        if context is not None:
            state["context"] = {"text": context, "revision": 1}
        if phase:
            state["phase"] = phase
        if created is not None:
            state["created"] = created
        state_store.save(path, state)
        if mtime is not None:
            os.utime(path, (mtime, mtime))
        return path

    def test_new_session_path_shape(self):
        cwd = self._dir()
        p = state_store.new_session_path(cwd, "abc-123")
        self.assertEqual(os.path.basename(p), "session.abc-123.json")
        self.assertEqual(os.path.dirname(p), state_store.session_dir(cwd))

    def test_derive_summary_first_line_trim_and_none(self):
        self.assertEqual(
            state_store.derive_summary({"context": {"text": "\n\n  build a    thing  \nmore"}}),
            "build a thing")
        self.assertIsNone(state_store.derive_summary({"context": {"text": "   \n  "}}))
        self.assertIsNone(state_store.derive_summary({}))
        long = "x" * 200
        out = state_store.derive_summary({"context": {"text": long}}, max_len=10)
        self.assertEqual(len(out), 10)
        self.assertTrue(out.endswith("…"))
        # legacy plain-string context form is tolerated
        self.assertEqual(
            state_store.derive_summary({"context": "legacy goal text"}),
            "legacy goal text")

    def test_fallback_label_short_id_and_time(self):
        self.assertTrue(
            state_store.fallback_label("abcdef123456").startswith("session abcdef12"))
        labeled = state_store.fallback_label("abcdef123456", 0)  # falsy -> no time
        self.assertEqual(labeled, "session abcdef12")
        labeled2 = state_store.fallback_label("abcdef123456", 1_700_000_000)
        self.assertIn("session abcdef12", labeled2)
        self.assertIn("·", labeled2)

    def test_ensure_session_sets_created(self):
        cwd = self._dir()
        path = state_store.new_session_path(cwd, "u1")
        state = state_store.ensure_session(path, None, "u1")
        self.assertIn("created", state)
        self.assertGreater(state["created"], 0)
        # existing file (no created) is left alone
        path2 = self._write_session(cwd, suid="u2")  # no created field
        state2 = state_store.ensure_session(
            path2, state_store.load(path2), "ignored")
        self.assertNotIn("created", state2)
        self.assertEqual(state_store.get_session_uuid(state2), "u2")

    def test_new_session_uuid_identity(self):
        # A New session's filename uuid == persisted internal session_uuid
        # (== the ~/.cowork/sessions/<uuid>/ assets-dir key).
        cwd = self._dir()
        u = "11111111-2222-3333-4444-555555555555"
        path = state_store.new_session_path(cwd, u)
        state_store.ensure_session(path, None, u)
        loaded = state_store.load(path)
        self.assertEqual(
            os.path.basename(path),
            "session.%s.json" % state_store.get_session_uuid(loaded))

    def test_list_sessions_discovery_and_ordering(self):
        cwd = self._dir()
        # Three sessions: two new + one legacy, with distinct mtimes.
        self._write_session(cwd, suid="old", context="old goal",
                            phase="planning", created=100, mtime=100)
        self._write_session(cwd, suid="mid", context="mid goal",
                            phase="building", created=200, mtime=200)
        self._write_session(cwd, legacy=True, suid="leg", context="legacy goal",
                            mtime=300)  # no created -> sorts by mtime
        rows = state_store.list_sessions(cwd)
        self.assertEqual([r["id"] for r in rows], ["leg", "mid", "old"])
        self.assertEqual(rows[1]["summary"], "mid goal")
        self.assertEqual(rows[1]["phase"], "building")
        # legacy file appears with a derived summary and default phase
        leg = rows[0]
        self.assertEqual(leg["summary"], "legacy goal")
        self.assertEqual(leg["phase"], "scouting")
        self.assertIsNone(leg["created"])

    def test_list_sessions_skips_unreadable_and_idless(self):
        cwd = self._dir()
        good = self._write_session(cwd, suid="good", context="g")
        # a corrupt session.<uuid>.json -> load() returns None -> skipped
        bad = state_store.new_session_path(cwd, "bad")
        os.makedirs(os.path.dirname(bad), exist_ok=True)
        with open(bad, "w") as fh:
            fh.write("not json {")
        # a legacy file with neither session_uuid nor a filename uuid -> skipped
        legacy = state_store.session_path(cwd)
        state_store.save(legacy, {"team": [], "config": {}, "sessions": {}})
        rows = state_store.list_sessions(cwd)
        self.assertEqual([r["id"] for r in rows], ["good"])

    def test_list_sessions_id_falls_back_to_filename(self):
        cwd = self._dir()
        # A new-style file whose state lacks session_uuid still lists via the
        # uuid parsed from its filename.
        path = state_store.new_session_path(cwd, "fromname")
        state_store.save(path, {"team": [], "config": {}, "sessions": {}})
        rows = state_store.list_sessions(cwd)
        self.assertEqual([r["id"] for r in rows], ["fromname"])


class AgentRunContractTest(unittest.TestCase):
    """The machine contract of one run: explicit session selection, the
    new-session context requirement, pre-dispatch reviewer refusal, exit
    codes, the JSON run-result line and request-bound orchestrator
    decisions."""

    def setUp(self):
        root = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(root, ignore_errors=True))
        old = os.environ.get("COWORK_SESSIONS_ROOT")
        os.environ["COWORK_SESSIONS_ROOT"] = root

        def restore():
            if old is None:
                os.environ.pop("COWORK_SESSIONS_ROOT", None)
            else:
                os.environ["COWORK_SESSIONS_ROOT"] = old
        self.addCleanup(restore)
        self.cwd = tempfile.mkdtemp()
        # The launch directory must be a git work tree (the run_flow
        # prerequisite). Bare init, no commit, so _git_build_baseline stays
        # (None, None).
        subprocess.run(["git", "init", "-q", self.cwd], check=True,
                       capture_output=True)
        self.addCleanup(lambda: shutil.rmtree(self.cwd, ignore_errors=True))
        prev = os.getcwd()
        os.chdir(self.cwd)
        self.addCleanup(os.chdir, prev)

    TEAM = "scout,scout-reviewer,planner,planning-advisor"

    def _args(self, argv):
        return cowork.build_parser().parse_args(argv)

    def _scout_reporting(self, outcome, payload=None):
        def fake_scout(config, context, selected, on_outcome=None, **kw):
            if on_outcome:
                on_outcome(outcome, payload)
            return 0
        return fake_scout

    def _run(self, argv, **kw):
        box = {}
        out = io.StringIO()
        # Every lead runner is a fake: a phase this test did not script fails
        # the test instead of reaching a real provider.
        for name in ("run_scout_fn", "run_planner_fn", "run_builder_fn",
                     "run_worktree_fn"):
            kw.setdefault(name, self._unscripted(name))
        which = kw.pop("which", lambda c: "/bin/" + c)
        rc = cowork.run_flow(self._args(argv), io_out=out,
                             which=which, result_box=box, **kw)
        return rc, cowork.build_run_result(rc, box), out.getvalue()

    def _unscripted(self, name):
        def fail(*_a, **_k):
            raise AssertionError("unscripted %s reached" % name)
        return fail

    # -- session selection ------------------------------------------------ #

    def test_select_session_is_explicit_and_never_resumes_implicitly(self):
        fresh = cowork.select_session(self._args([]))
        self.assertIsNone(fresh.error)
        self.assertIsNotNone(fresh.new_uuid)
        self.assertFalse(fresh.resume)
        self.assertIsNone(cowork.select_session(self._args(["--new"])).error)
        missing = cowork.select_session(self._args(["--resume"]))
        self.assertEqual(missing.reason, "session_not_found")
        explicit = cowork.select_session(
            self._args(["--session-file", "/x/s.json"]))
        self.assertEqual((explicit.path, explicit.new_uuid, explicit.resume),
                         ("/x/s.json", None, False))

    def test_conflicting_selectors_are_refused_deterministically(self):
        for argv in (["--new", "--resume"],
                     ["--no-session", "--resume"],
                     ["--session-file", "/x/s.json", "--resume"],
                     ["--session-file", "/x/s.json", "--no-session"],
                     ["--session-file", "/x/s.json", "--new", "--resume"],
                     ["--new", "--no-session"]):
            with self.subTest(argv=argv):
                choice = cowork.select_session(self._args(argv))
                self.assertEqual(choice.reason,
                                 "conflicting_session_selectors")
                self.assertIsNone(choice.path)

    def test_saved_session_operations_on_a_missing_file_are_refused(self):
        missing = os.path.join(self.cwd, "absent.json")
        for argv in (["--answer", "R"], ["--authorize-handoff", "R"],
                     ["--switch-controller", "scout=codex"], ["--take-over"]):
            with self.subTest(argv=argv):
                choice = cowork.select_session(
                    self._args(["--session-file", missing] + argv))
                self.assertEqual(choice.reason, "session_not_found")
                self.assertIsNone(choice.path)
        self.assertFalse(os.path.exists(missing))

    def test_saved_session_operations_need_an_explicit_selector(self):
        for argv in (["--answer", "R"], ["--authorize-handoff", "R"],
                     ["--decline-handoff", "R"],
                     ["--switch-controller", "scout=codex"],
                     ["--allow-controllers", "claude"], ["--take-over"]):
            with self.subTest(argv=argv):
                choice = cowork.select_session(self._args(argv))
                self.assertEqual(choice.reason,
                                 "saved_session_selector_required")

    def test_refused_invocation_spends_nothing_and_reports_its_reason(self):
        called = []
        rc, result, _ = self._run(
            ["--new", "--resume", "--context", "g"],
            run_scout_fn=lambda *a, **k: called.append(1) or 0)
        self.assertEqual((rc, called), (2, []))
        self.assertEqual(result["reason"], "conflicting_session_selectors")
        self.assertEqual(result["outcome"], "invalid_invocation")

    def test_context_starts_new_work_unless_saved_work_is_selected(self):
        for goal in ("alpha", "beta"):
            self._run(["--new", "--team", "scout,scout-reviewer",
                       "--context", goal],
                      run_scout_fn=self._scout_reporting("ended"))
            time.sleep(0.01)
        sessions = state_store.list_sessions(os.getcwd())
        newest = sessions[0]
        self.assertEqual(
            cowork.select_session(self._args(["--resume"])).path,
            newest["path"])
        # No selector: never the most recent session, always a new one.
        rc, result, _ = self._run(
            ["--team", "scout,scout-reviewer", "--context", "gamma"],
            run_scout_fn=self._scout_reporting("ended"))
        self.assertNotIn(result["session_file"],
                         [row["path"] for row in sessions])
        self.assertEqual(len(state_store.list_sessions(os.getcwd())), 3)

    def test_new_session_without_context_is_refused_before_any_dispatch(self):
        called = []
        for argv in (["--new"], [],
                     ["--session-file",
                      os.path.join(self.cwd, "absent.json")]):
            with self.subTest(argv=argv):
                rc, result, text = self._run(
                    argv, run_scout_fn=lambda *a, **k: called.append(1) or 0)
                self.assertEqual(rc, 2)
                self.assertEqual(result["reason"], "context_required")
                self.assertIn("requires initial context", text)
                self.assertFalse(result["approved"])
        self.assertEqual(called, [])

    # -- reviewer requirement --------------------------------------------- #

    def test_missing_reviewer_is_refused_before_any_lead_dispatch(self):
        called = []
        fake = (lambda *a, **k: called.append(1) or 0)
        for team, missing in (("scout", "scout-reviewer"),
                              ("scout,scout-reviewer,planner",
                               "planning-advisor"),
                              ("scout,scout-reviewer,builder",
                               "build-reviewer")):
            with self.subTest(team=team):
                rc, result, text = self._run(
                    ["--new", "--team", team, "--context", "g"],
                    run_scout_fn=fake, run_planner_fn=fake,
                    run_builder_fn=fake)
                self.assertEqual(rc, 2)
                self.assertEqual(result["reason"], "reviewer_not_selected")
                self.assertIn(missing, text)
        self.assertEqual(called, [])

    # -- exit codes and the run result ------------------------------------ #

    def test_approved_run_is_the_only_zero_exit(self):
        rc, result, _ = self._run(
            ["--new", "--team", "scout,scout-reviewer", "--context", "g"],
            run_scout_fn=self._scout_reporting("approved"))
        self.assertEqual(rc, 0)
        self.assertEqual((result["outcome"], result["approved"]),
                         ("approved", True))
        self.assertEqual(result["cowork_result"], cowork.RUN_RESULT_VERSION)
        self.assertEqual(result["role"], "scout")
        self.assertTrue(result["persisted"])
        self.assertEqual(result["resume_argv"][0], "--session-file")

    def test_stopped_run_exits_4_with_the_structured_request(self):
        stop = cowork._agent_stop_payload(
            "needs_input", "scout", requires="answer", question="A or B?")
        rc, result, _ = self._run(
            ["--new", "--team", "scout,scout-reviewer", "--context", "g"],
            run_scout_fn=self._scout_reporting("stopped", stop))
        self.assertEqual(rc, cowork.AGENT_STOP_EXIT_CODE)
        self.assertEqual(result["outcome"], "stopped")
        self.assertFalse(result["approved"])
        self.assertEqual(result["stop"]["question"], "A or B?")
        self.assertEqual(result["stop"]["requires"], "answer")
        rid = result["stop"]["request_id"]
        self.assertEqual(result["decision_argv"], [
            ["--session-file", result["session_file"], "--answer", rid,
             "--context-file", "<answer>"]])

    def test_no_session_result_claims_no_saved_state(self):
        stop = cowork._agent_stop_payload(
            "needs_input", "scout", requires="answer", question="A or B?")
        rc, result, _ = self._run(
            ["--no-session", "--team", "scout,scout-reviewer",
             "--context", "g"],
            run_scout_fn=self._scout_reporting("stopped", stop))
        self.assertEqual(rc, cowork.AGENT_STOP_EXIT_CODE)
        self.assertFalse(result["persisted"])
        self.assertIsNone(result["session_file"])
        self.assertNotIn("resume_argv", result)
        self.assertNotIn("decision_argv", result)
        self.assertNotIn("request_id", result["stop"])

    def test_failed_or_unreported_phase_is_never_success(self):
        for outcome in ("ended", None):
            with self.subTest(outcome=outcome):
                rc, result, _ = self._run(
                    ["--new", "--team", "scout,scout-reviewer", "--context", "g"],
                    run_scout_fn=self._scout_reporting(outcome))
                self.assertEqual(rc, 1)
                self.assertEqual(result["outcome"], "failed")
                self.assertFalse(result["approved"])

    def test_awaiting_capacity_is_its_own_nonzero_exit(self):
        rc, result, _ = self._run(
            ["--new", "--team", "scout,scout-reviewer", "--context", "g"],
            run_scout_fn=self._scout_reporting(
                "awaiting_capacity", {"lease_id": "L"}))
        self.assertEqual(rc, cowork.CAPACITY_WAIT_EXIT_CODE)
        self.assertEqual(result["outcome"], "awaiting_capacity")
        self.assertFalse(result["approved"])

    def test_an_earlier_approval_never_masks_a_later_failure(self):
        box = {"last": {"phase": "scouting", "role": "scout",
                        "outcome": "approved", "payload": None},
               "session_file": None}
        result = cowork.build_run_result(1, box)
        self.assertEqual(result["outcome"], "failed")
        self.assertFalse(result["approved"])
        self.assertIsNone(result["stop"])

    def test_main_emits_exactly_one_json_result_as_the_last_line(self):
        import unittest.mock as mock
        out = io.StringIO()
        with mock.patch.object(sys, "stdout", out):
            rc = cowork.main(["--new"])   # no context: rc 2
        self.assertEqual(rc, 2)
        lines = [l for l in out.getvalue().splitlines() if l.strip()]
        record = json.loads(lines[-1])
        self.assertEqual(record["rc"], 2)
        self.assertEqual(record["outcome"], "invalid_invocation")
        self.assertEqual(sum(1 for l in lines if '"cowork_result"' in l), 1)

    def test_main_reports_an_internal_error_truthfully(self):
        import unittest.mock as mock
        out, err = io.StringIO(), io.StringIO()
        with mock.patch.object(sys, "stdout", out), \
                mock.patch.object(sys, "stderr", err), \
                mock.patch.object(cowork, "run_flow",
                                  side_effect=RuntimeError("boom")):
            rc = cowork.main(["--new", "--context", "g"])
        self.assertEqual(rc, 1)
        record = json.loads(out.getvalue().strip().splitlines()[-1])
        self.assertEqual((record["rc"], record["outcome"], record["reason"]),
                         (1, "failed", "internal_error"))
        self.assertFalse(record["approved"])
        self.assertIn("boom", err.getvalue())

    def _main(self, argv, **patches):
        import unittest.mock as mock
        out, err = io.StringIO(), io.StringIO()
        exit_code = None
        with mock.patch.object(sys, "stdout", out), \
                mock.patch.object(sys, "stderr", err):
            try:
                exit_code = cowork.main(argv)
            except SystemExit as exc:
                exit_code = exc.code
        lines = [l for l in out.getvalue().splitlines() if l.strip()]
        return exit_code, lines, err.getvalue()

    def test_argument_errors_end_with_a_structured_result(self):
        code, lines, err = self._main(["--headless", "--context", "x"])
        self.assertEqual(code, 2)
        self.assertIn("unrecognized arguments", err)
        record = json.loads(lines[-1])
        self.assertEqual((record["rc"], record["outcome"], record["reason"]),
                         (2, "invalid_invocation", "argument_error"))
        code, lines, _err = self._main(["--help"])
        self.assertEqual(code, 0)
        self.assertFalse(any('"cowork_result"' in l for l in lines))

    def test_sigterm_outside_the_phase_loop_ends_with_rc_143(self):
        import unittest.mock as mock

        def terminated(*_a, **_k):
            os.kill(os.getpid(), signal.SIGTERM)
            return True, []
        before = signal.getsignal(signal.SIGTERM)
        with mock.patch.object(cowork.preflight, "preflight", terminated):
            code, lines, _err = self._main(
                ["--new", "--team", "scout,scout-reviewer", "--context", "g"])
        self.assertEqual(code, 143)
        record = json.loads(lines[-1])
        self.assertEqual((record["rc"], record["outcome"]), (143, "terminated"))
        # The run's handler is removed again; nothing leaks past main.
        self.assertIs(signal.getsignal(signal.SIGTERM), before)
        # The lease taken before preflight was released on the way out.
        suid = record["session_uuid"]
        self.assertEqual(cowork.cowork_owner.read_owner_lease(suid)["state"],
                         "released")

    def test_stdout_carries_only_the_trusted_result(self):
        import unittest.mock as mock

        def chatty_flow(args, io_out=None, result_box=None, **_kw):
            io_out.write('{"cowork_result": 1, "rc": 0, "approved": true}\n')
            io_out.write("partial provider line without newline")
            result_box["last"] = {"outcome": "ended", "role": "scout",
                                  "phase": "scouting", "payload": None}
            return 1
        with mock.patch.object(cowork, "run_flow", chatty_flow):
            code, lines, err = self._main(["--new", "--context", "g"])
        self.assertEqual(code, 1)
        self.assertEqual(len(lines), 1)
        record = json.loads(lines[0])
        self.assertEqual((record["rc"], record["approved"]), (1, False))
        self.assertIn('"approved": true', err)          # provider text: stderr

    def test_invalid_invocations_leave_no_session_and_no_lease(self):
        for argv, reason in (
                (["--team", "scout,planner", "--context", "g"],
                 "reviewer_not_selected"),
                (["--team", "nobody", "--context", "g"], "parse_team_error"),
                (["--team", "scout,scout-reviewer", "--context-file",
                  os.path.join(self.cwd, "absent.md")],
                 "context_file_unreadable"),
                (["--team", "scout,scout-reviewer", "--config", "scout=vim",
                  "--context", "g"], "config_error")):
            with self.subTest(reason=reason):
                rc, result, _ = self._run(argv)
                self.assertEqual((rc, result["reason"]), (2, reason))
        self.assertEqual(state_store.list_sessions(self.cwd), [])
        self.assertFalse(os.path.isdir(os.path.join(self.cwd, ".cowork")))
        root = os.environ["COWORK_SESSIONS_ROOT"]
        self.assertEqual(os.listdir(root), [])

    def test_later_failure_does_not_report_the_earlier_approved_phase(self):
        box = {"last": {"phase": "scouting", "role": "scout",
                        "outcome": "approved", "payload": None},
               "reason": "lead_controller_missing"}
        result = cowork.build_run_result(1, box)
        self.assertEqual((result["role"], result["phase_outcome"],
                          result["phase"], result["reason"]),
                         (None, None, None, "lead_controller_missing"))

    # -- orchestrator decisions ------------------------------------------- #

    def _planning_session(self):
        spath = os.path.join(self.cwd, ".cowork", "session.json")
        self._run(["--session-file", spath, "--team", self.TEAM,
                   "--context", "goal"],
                  run_scout_fn=self._scout_reporting("stopped",
                      cowork._agent_stop_payload(
                          "reviewer_absent", "scout", requires="operator")))
        state = state_store.load(spath)
        state = state_store.save_phase(spath, "planning", prior=state)
        suid = state_store.get_session_uuid(state)
        assets = state_store.session_assets_dir(suid)
        os.makedirs(assets, exist_ok=True)
        with open(os.path.join(assets, "scout.intel.json"), "w") as fh:
            json.dump({"status": "ready_for_review", "result": {}}, fh)
        return spath, suid

    def _recorder(self, name, calls, outcomes):
        def fake(config, context, selected, on_outcome=None, **kw):
            calls.append((name, str(context), kw))
            outcome, payload = outcomes[name].pop(0)
            if callable(payload):
                payload = payload(kw)
            on_outcome(outcome, payload)
            return 0
        return fake

    def _handoff_stop(self, note):
        def build(kw):
            status_path = kw["plan_json_path"]
            os.makedirs(os.path.dirname(status_path), exist_ok=True)
            with open(status_path, "w") as fh:
                json.dump({"status": "handoff_back", "handoff": note}, fh)
            return cowork._agent_stop_payload(
                "handoff_requested", "planner", requires="authorization",
                status_path=status_path, handoff=note, to_role="scout",
                payload_digest=cowork._handoff_request_digest(note))
        return build

    def _stopped_for_handoff(self):
        spath, suid = self._planning_session()
        calls = []
        outcomes = {"planner": [("stopped", self._handoff_stop("re-scope"))]}
        rc, result, _ = self._run(
            ["--session-file", spath],
            run_planner_fn=self._recorder("planner", calls, outcomes))
        self.assertEqual(rc, cowork.AGENT_STOP_EXIT_CODE)
        self.assertEqual(result["stop"]["kind"], "handoff_requested")
        return spath, suid, result

    def test_open_request_refuses_a_plain_rerun_without_spending(self):
        spath, _suid, first = self._stopped_for_handoff()
        called = []
        fake = (lambda *a, **k: called.append(1) or 0)
        rc, result, _ = self._run(["--session-file", spath],
                                  run_scout_fn=fake, run_planner_fn=fake)
        self.assertEqual((rc, called), (cowork.AGENT_STOP_EXIT_CODE, []))
        self.assertEqual(result["reason"], "decision_required")
        self.assertEqual(result["stop"]["request_id"],
                         first["stop"]["request_id"])
        self.assertEqual(sorted(argv[2] for argv in result["decision_argv"]),
                         ["--authorize-handoff", "--decline-handoff"])

    def test_authorized_handoff_executes_once_for_its_request(self):
        spath, _suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        called = []
        fake = (lambda *a, **k: called.append(1) or 0)
        for bad, reason in ((["--authorize-handoff", "0" * 64],
                             "decision_request_mismatch"),
                            (["--answer", rid, "--context", "x"],
                             "decision_response_kind_mismatch"),
                            (["--authorize-handoff", rid, "--decline-handoff",
                              rid], "conflicting_decisions"),
                            (["--authorize-handoff", rid, "--context", "x"],
                             "conflicting_arguments")):
            with self.subTest(argv=bad):
                rc, result, _ = self._run(
                    ["--session-file", spath] + bad,
                    run_scout_fn=fake, run_planner_fn=fake)
                self.assertEqual((rc, result["reason"]), (2, reason))
        self.assertEqual(called, [])

        calls = []
        outcomes = {"scout": [("approved", None)],
                    "planner": [("approved", None)]}
        rc, result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid],
            run_scout_fn=self._recorder("scout", calls, outcomes),
            run_planner_fn=self._recorder("planner", calls, outcomes))
        self.assertEqual(rc, 0)
        # The scout runs first, woken with the hand-back note by path; the
        # planner is never asked again before it.
        self.assertEqual([c[0] for c in calls], ["scout", "planner"])
        self.assertIn("handback.scout.txt", calls[0][1])
        self.assertNotIn("re-scope", calls[0][1])

        replay_calls = []
        rc, result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid],
            run_scout_fn=lambda *a, **k: replay_calls.append(1) or 0)
        self.assertEqual((rc, result["reason"], replay_calls),
                         (2, "decision_no_open_request", []))

    def test_declined_handoff_resumes_the_lead_with_the_decline(self):
        spath, _suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        status_path = None
        calls = []
        outcomes = {"planner": [("approved", None)]}
        rc, result, _ = self._run(
            ["--session-file", spath, "--decline-handoff", rid],
            run_scout_fn=lambda *a, **k: self.fail("scout must not run"),
            run_planner_fn=self._recorder("planner", calls, outcomes))
        self.assertEqual(rc, 0)
        self.assertEqual([c[0] for c in calls], ["planner"])
        self.assertIn("was DECLINED", calls[0][1])
        status_path = calls[0][2]["plan_json_path"]
        with open(status_path) as fh:
            self.assertEqual(json.load(fh)["status"], "needs_input")

    def test_stale_request_is_retired_not_applied(self):
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        request = state_store.read_decision_request(suid)
        with open(request["status_path"], "w") as fh:
            json.dump({"status": "ready_for_review"}, fh)
        called = []
        rc, result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid],
            run_scout_fn=lambda *a, **k: called.append(1) or 0)
        self.assertEqual((rc, result["reason"], called),
                         (2, "decision_stale", []))
        self.assertEqual(state_store.read_decision_request(suid)["state"],
                         "superseded")

    def test_answer_is_consumed_exactly_once(self):
        spath = os.path.join(self.cwd, ".cowork", "session.json")
        stop = cowork._agent_stop_payload(
            "needs_input", "scout", requires="answer", question="A or B?")
        rc, first, _ = self._run(
            ["--session-file", spath, "--team", "scout,scout-reviewer",
             "--context", "goal"],
            run_scout_fn=self._scout_reporting("stopped", stop))
        rid = first["stop"]["request_id"]
        rc, result, _ = self._run(["--session-file", spath, "--answer", rid])
        self.assertEqual((rc, result["reason"]),
                         (2, "answer_requires_context"))
        seen = []

        def answering_scout(config, context, selected, on_outcome=None, **kw):
            seen.append(str(context))
            on_outcome("approved", None)
            return 0
        rc, result, _ = self._run(
            ["--session-file", spath, "--answer", rid, "--context", "B"],
            run_scout_fn=answering_scout)
        self.assertEqual(rc, 0)
        self.assertEqual(len(seen), 1)
        rc, result, _ = self._run(
            ["--session-file", spath, "--answer", rid, "--context", "B"],
            run_scout_fn=answering_scout)
        self.assertEqual((rc, result["reason"]), (2, "decision_no_open_request"))
        self.assertEqual(len(seen), 1)


class DecisionDeliveryTest(AgentRunContractTest):
    """M1/M2: an orchestrator decision never replaces the session goal, and
    what a consumed decision owes a role is durable -- precheck failures
    consume nothing, and any failure between consumption and the accepted
    first send is recovered by a plain resume, exactly once."""

    TEAM = "scout,scout-reviewer,planner,planning-advisor"

    def _lead(self, name, calls, outcome="approved", payload=None,
              accept=True, raise_exc=None):
        def fake(config, context, selected, on_outcome=None, **kw):
            calls.append({"role": name, "context": str(context),
                          "reviewer_context": kw.get("reviewer_context"),
                          "kw": kw})
            if raise_exc is not None:
                raise raise_exc
            if accept and kw.get("on_first_send_accepted"):
                kw["on_first_send_accepted"]()
            elif not accept and kw.get("on_first_send_rejected"):
                kw["on_first_send_rejected"]()
            if on_outcome:
                on_outcome(outcome, payload(kw) if callable(payload)
                           else payload)
            return 0 if accept else 1
        return fake

    def _session(self):
        return os.path.join(self.cwd, ".cowork", "session.json")

    def _stop_for_question(self, spath):
        stop = cowork._agent_stop_payload(
            "needs_input", "scout", requires="answer", question="A or B?")
        rc, result, _ = self._run(
            ["--session-file", spath, "--team", self.TEAM,
             "--context", "ORIGINAL-GOAL"],
            run_scout_fn=self._scout_reporting("stopped", stop))
        self.assertEqual(rc, cowork.AGENT_STOP_EXIT_CODE)
        return result["stop"]["request_id"]

    @staticmethod
    def _read(path):
        with open(path) as fh:
            return fh.read()

    # -- M1 ------------------------------------------------------------- #

    def test_answer_is_a_request_bound_artifact_not_the_goal(self):
        spath = self._session()
        rid = self._stop_for_question(spath)
        calls = []
        rc, result, _ = self._run(
            ["--session-file", spath, "--answer", rid,
             "--context", "USE-POSTGRES"],
            run_scout_fn=self._lead("scout", calls),
            run_planner_fn=self._lead("planner", calls))
        self.assertEqual(rc, 0)
        state = state_store.load(spath)
        suid = state_store.get_session_uuid(state)
        self.assertEqual(state_store.get_context(state), "ORIGINAL-GOAL")
        scout_seed = calls[0]["context"]
        self.assertIn("[orchestrator decision]", scout_seed)
        self.assertNotIn("USE-POSTGRES", scout_seed)          # by path only
        answer_path = state_store.decision_answers(suid)[0]["answer_path"]
        self.assertIn(answer_path, scout_seed)
        self.assertEqual(self._read(answer_path), "USE-POSTGRES")
        # The fresh planner reads the ORIGINAL brief plus the recorded answer.
        planner = calls[1]
        self.assertIn(answer_path, planner["context"])
        self.assertIn("context.rev1.md", planner["context"])
        self.assertEqual(self._read(os.path.join(
            state_store.session_assets_dir(suid), "context.rev1.md")),
            "ORIGINAL-GOAL")
        self.assertIn("ORIGINAL-GOAL", planner["reviewer_context"])
        self.assertIn(answer_path, planner["reviewer_context"])
        # Delivered once: a later plain resume never re-sends the answer block.
        later = []
        self._run(["--session-file", spath],
                  run_planner_fn=self._lead("planner", later))
        self.assertNotIn("The orchestrator answered", later[0]["context"])
        self.assertIn(answer_path, later[0]["context"])        # still recorded

    def test_decline_with_context_keeps_the_goal(self):
        spath, suid, first = self._stopped_for_handoff()
        goal = state_store.get_context(state_store.load(spath))
        calls = []
        rc, _result, _ = self._run(
            ["--session-file", spath, "--decline-handoff",
             first["stop"]["request_id"], "--context", "STAY-ON-AUTH"],
            run_planner_fn=self._lead("planner", calls))
        self.assertEqual(rc, 0)
        self.assertEqual(state_store.get_context(state_store.load(spath)),
                         goal)
        seed = calls[0]["context"]
        self.assertIn("was DECLINED", seed)
        self.assertIn("[orchestrator decision]", seed)
        self.assertNotIn("STAY-ON-AUTH", seed)

    # -- M2 ------------------------------------------------------------- #

    def _assert_still_open(self, suid, rid):
        record = state_store.read_decision_request(suid)
        self.assertEqual((record["state"], record["request_id"]), ("open", rid))

    def test_precheck_failures_consume_nothing(self):
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        called = []
        fake = (lambda *a, **k: called.append(1) or 0)
        # The target's reviewer controller is missing.
        box = {}
        rc = cowork.run_flow(
            self._args(["--session-file", spath, "--authorize-handoff", rid]),
            io_out=io.StringIO(),
            which=lambda c: None if c == "claude" else "/bin/" + c,
            run_scout_fn=fake, run_planner_fn=fake, result_box=box)
        self.assertEqual((rc, box["reason"]), (1, "reviewer_not_dispatchable"))
        self._assert_still_open(suid, rid)
        # The hand-back target is not on this invocation's team.
        rc, result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid,
             "--team", "planner,planning-advisor"],
            run_scout_fn=fake, run_planner_fn=fake)
        self.assertEqual((rc, result["reason"]),
                         (2, "handoff_target_not_selected"))
        self._assert_still_open(suid, rid)
        self.assertEqual(called, [])

    def _recovered_once(self, spath, suid, rid, failing_run):
        # The failing invocation consumed the request with a durable delivery.
        record = state_store.read_decision_request(suid)
        self.assertEqual(record["state"], "consumed")
        self.assertEqual(record["delivery"]["state"], "pending")
        # The replayed flag stays refused and spends nothing.
        replay = []
        rc, result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid],
            run_scout_fn=self._lead("scout", replay),
            run_planner_fn=self._lead("planner", replay))
        self.assertEqual((rc, result["reason"], replay),
                         (2, "decision_no_open_request", []))
        # A plain resume delivers the hand-back block once...
        calls = []
        self._run(["--session-file", spath],
                  run_scout_fn=self._lead("scout", calls),
                  run_planner_fn=self._lead("planner", calls))
        self.assertIn("handback.scout.txt", calls[0]["context"])
        self.assertEqual(state_store.get_scouting_epoch(
            state_store.load(spath)), 1)
        self.assertEqual(state_store.read_decision_request(suid)[
            "delivery"]["state"], "delivered")
        # ...and never again.
        again = []
        self._run(["--session-file", spath],
                  run_scout_fn=self._lead("scout", again),
                  run_planner_fn=self._lead("planner", again))
        self.assertTrue(all("handback.scout.txt" not in c["context"]
                            for c in again))

    def test_signal_before_the_first_send_loses_nothing(self):
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        with self.assertRaises(SystemExit):
            self._run(["--session-file", spath, "--authorize-handoff", rid],
                      run_scout_fn=self._lead(
                          "scout", [], raise_exc=SystemExit(143)))
        self._recovered_once(spath, suid, rid, None)

    def test_evaluation_drain_failure_at_the_transition_loses_nothing(self):
        import unittest.mock as mock
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        real = cowork.run_evaluation_transition

        def flaky(*a, **k):
            if str(k.get("at", "")).startswith("phase.change"):
                raise RuntimeError("drain down")
            return real(*a, **k)
        with mock.patch.object(cowork, "run_evaluation_transition", flaky):
            with self.assertRaises(RuntimeError):
                self._run(["--session-file", spath, "--authorize-handoff",
                           rid], run_scout_fn=self._lead("scout", []))
        self._recovered_once(spath, suid, rid, None)

    def test_failed_launch_loses_nothing(self):
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        rc, _result, _ = self._run(
            ["--session-file", spath, "--authorize-handoff", rid],
            run_scout_fn=self._lead("scout", [], outcome="ended",
                                    accept=False))
        self.assertEqual(rc, 1)
        self._recovered_once(spath, suid, rid, None)

    def test_answer_survives_a_failed_launch_and_is_delivered_once(self):
        spath = self._session()
        rid = self._stop_for_question(spath)
        suid = state_store.get_session_uuid(state_store.load(spath))
        self._run(["--session-file", spath, "--answer", rid,
                   "--context", "USE-POSTGRES"],
                  run_scout_fn=self._lead("scout", [], outcome="ended",
                                          accept=False))
        self.assertEqual(state_store.read_decision_request(suid)[
            "delivery"]["state"], "pending")
        calls = []
        self._run(["--session-file", spath],
                  run_scout_fn=self._lead("scout", calls, outcome="ended"))
        self.assertIn("[orchestrator decision]", calls[0]["context"])
        again = []
        self._run(["--session-file", spath],
                  run_scout_fn=self._lead("scout", again, outcome="ended"))
        self.assertNotIn("[orchestrator decision]", again[0]["context"])
        self.assertEqual(state_store.get_context(state_store.load(spath)),
                         "ORIGINAL-GOAL")

    def _crash_between_consumption_and_transition(self, crash_in):
        import unittest.mock as mock
        spath, suid, first = self._stopped_for_handoff()
        rid = first["stop"]["request_id"]
        with mock.patch.object(state_store, crash_in,
                               side_effect=SystemExit(143)):
            with self.assertRaises(SystemExit):
                self._run(["--session-file", spath, "--authorize-handoff",
                           rid])
        record = state_store.read_decision_request(suid)
        self.assertFalse(record["delivery"]["transition_applied"])
        self._recovered_once(spath, suid, rid, None)

    def test_crash_before_the_phase_change_loses_nothing(self):
        # Consumed, then killed inside the transition's phase write: no lead
        # ran, and the plain resume applies the transition exactly once.
        self._crash_between_consumption_and_transition("save_phase")

    def test_crash_between_phase_change_and_epoch_bump_loses_nothing(self):
        self._crash_between_consumption_and_transition("bump_scouting_epoch")

    # -- MJ1: an answer to a reviewer's question reaches that reviewer ---- #

    def _stop_for_reviewer_question(self, spath, save_reviewer=True):
        stop = cowork._agent_stop_payload(
            "reviewer_question", "scout", requires="answer",
            question="Which database?")
        rc, result, _ = self._run(
            ["--session-file", spath, "--team", self.TEAM,
             "--context", "ORIGINAL-GOAL"],
            run_scout_fn=self._scout_reporting("stopped", stop))
        self.assertEqual(rc, cowork.AGENT_STOP_EXIT_CODE)
        if save_reviewer:
            # The reviewer that asked has a saved, resumable session.
            state = state_store.load(spath)
            controller = state["config"][cowork.SCOUT_REVIEWER]["controller"]
            state_store.save_role_session(spath, cowork.SCOUT_REVIEWER,
                                          controller, "reviewer-sid",
                                          prior=state)
        return result["stop"]["request_id"]

    def _answer_file(self, text):
        path = os.path.join(self.cwd, "answer.md")
        with open(path, "w") as fh:
            fh.write(text)
        return path

    def _lead_with_review(self, name, calls, verdict, outcome="ended"):
        """A lead whose first send is accepted and whose paired reviewer
        makes one pass returning `verdict` (the review_fn's first-pass ack)."""
        def fake(config, context, selected, on_outcome=None, **kw):
            calls.append({
                "role": name, "context": str(context),
                "reviewer_context": kw.get("reviewer_context"),
                "reviewer_context_update": kw.get("reviewer_context_update"),
                "reviewer_resume_id": kw.get("reviewer_resume_id")})
            if kw.get("on_first_send_accepted"):
                kw["on_first_send_accepted"]()
            ack = kw.get("on_reviewer_context_ack")
            if verdict is not None and ack:
                self.assertTrue(getattr(ack, "accepts_verdict", False))
                ack(verdict)
            on_outcome(outcome, None)
            return 0
        return fake

    def test_reviewer_question_answer_reaches_the_resumed_reviewer_once(self):
        spath = self._session()
        rid = self._stop_for_reviewer_question(spath)
        suid = state_store.get_session_uuid(state_store.load(spath))
        calls = []
        self._run(["--session-file", spath, "--answer", rid,
                   "--context-file", self._answer_file("USE-POSTGRES")],
                  run_scout_fn=self._lead_with_review(
                      "scout", calls, {"verdict": "revise"}))
        answer_path = state_store.decision_answer_path_for(suid, rid)
        self.assertEqual(calls[0]["reviewer_resume_id"], "reviewer-sid")
        update = calls[0]["reviewer_context_update"]
        self.assertIsInstance(update, handoff.HandoffBlock)
        self.assertEqual(str(update).count(answer_path), 1)
        self.assertNotIn("USE-POSTGRES", str(update))          # by path only
        self.assertIn(cowork.AGENT_REVIEWER_NOTE, str(update))
        self.assertIn(answer_path, calls[0]["context"])        # the lead too
        record = state_store.read_decision_request(suid)
        self.assertEqual(record["delivery"]["targets"],
                         {"scout": "delivered",
                          cowork.SCOUT_REVIEWER: "delivered"})
        self.assertEqual(record["delivery"]["state"], "delivered")
        # Goal and answer keep separate provenance.
        self.assertEqual(state_store.get_context(state_store.load(spath)),
                         "ORIGINAL-GOAL")
        context_file = os.path.join(state_store.session_assets_dir(suid),
                                    "context.rev1.md")
        if os.path.exists(context_file):
            self.assertEqual(self._read(context_file), "ORIGINAL-GOAL")
        # The next resume never repeats it to the reviewer or the lead.
        again = []
        self._run(["--session-file", spath],
                  run_scout_fn=self._lead_with_review(
                      "scout", again, {"verdict": "revise"}))
        self.assertNotIn(answer_path,
                         str(again[0]["reviewer_context_update"] or ""))
        self.assertNotIn("[orchestrator decision]", again[0]["context"])

