def _init_git_repo():
    """Create a committed temp git repo and return its absolute path."""
    import tempfile
    d = os.path.realpath(tempfile.mkdtemp())
    subprocess.run(["git", "init", "-q", d], check=True)
    subprocess.run(["git", "-C", d, "config", "user.email", "t@t"], check=True)
    subprocess.run(["git", "-C", d, "config", "user.name", "t"], check=True)
    # Commit signing OFF in the scratch repo. A unit test that creates a
    # throwaway repo must not depend on the developer's global signing setup:
    # with `commit.gpgsign=true` in ~/.gitconfig these commits go through the
    # real signing agent, so an agent that is locked, timed out or simply
    # absent fails the commit with exit 128 and takes eleven unrelated
    # worktree tests down with it. Nothing here is testing signatures.
    subprocess.run(["git", "-C", d, "config", "commit.gpgsign", "false"],
                   check=True)
    subprocess.run(["git", "-C", d, "config", "tag.gpgsign", "false"],
                   check=True)
    with open(os.path.join(d, "f.txt"), "w") as fh:
        fh.write("x")
    subprocess.run(["git", "-C", d, "add", "."], check=True)
    subprocess.run(["git", "-C", d, "commit", "-qm", "init"], check=True)
    return d


class WorktreeFlagTest(unittest.TestCase):
    def _args(self, argv):
        return cowork.build_parser().parse_args(argv)

    def test_worktree_flag_optional_name(self):
        # no name -> const True
        a = self._args(["--worktree", "--context", "x"])
        self.assertIs(a.worktree, True)
        # explicit name
        a = self._args(["--wt", "feat-x", "--context", "x"])
        self.assertEqual(a.worktree, "feat-x")
        # absent
        a = self._args(["--context", "x"])
        self.assertIsNone(a.worktree)

    def test_wt_controller_default_and_choice(self):
        self.assertEqual(self._args(["--context", "x"]).wt_controller, "claude")
        self.assertEqual(
            self._args(["--wt-controller", "codex", "--context", "x"])
            .wt_controller, "codex")

    def test_removed_human_mode_flags_are_rejected(self):
        import contextlib
        for flag in ("--headless", "--auto"):
            with self.subTest(flag=flag):
                with contextlib.redirect_stderr(io.StringIO()):
                    with self.assertRaises(SystemExit) as caught:
                        self._args([flag, "--context", "x"])
                self.assertEqual(caught.exception.code, 2)
                self.assertNotIn(flag, cowork.build_parser().format_help())

    def test_default_worktree_name(self):
        self.assertEqual(cowork.default_worktree_name("abcdef0123456789"),
                         "cowork-abcdef01")


class WorktreeHelperTest(unittest.TestCase):
    def test_git_gate_inside_and_outside(self):
        repo = _init_git_repo()
        self.addCleanup(lambda: shutil.rmtree(repo, ignore_errors=True))
        self.assertEqual(cowork.git_worktree_toplevel(repo), repo)
        # a subdir of the repo still resolves to the toplevel
        sub = os.path.join(repo, "sub")
        os.makedirs(sub)
        self.assertEqual(cowork.git_worktree_toplevel(sub), repo)
        # a non-git dir -> None (the gate fails fast)
        import tempfile
        nongit = os.path.realpath(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(nongit, ignore_errors=True))
        self.assertIsNone(cowork.git_worktree_toplevel(nongit))

    def test_brief_carries_collision_policy(self):
        # Collision resolution is delegated to the agent prompt, so the brief
        # MUST carry the explicit-name reuse-or-fail policy and the auto-name
        # numeric-suffix policy — guard against a silent prompt regression.
        explicit = cowork.assemble_worktree_brief("/s.json", "/base", "feat",
                                                  True)
        self.assertIn("EXPLICITLY", explicit)
        self.assertIn("reuse", explicit.lower())
        self.assertIn("report failure", explicit.lower())
        auto = cowork.assemble_worktree_brief("/s.json", "/base", "cowork-ab",
                                              False)
        self.assertIn("AUTO-generated", auto)
        self.assertIn("numeric suffix", auto.lower())
        self.assertIn("cowork-ab-2", auto)

    def _make_worktree(self, repo, name):
        path = os.path.join(repo, ".worktrees", name)
        subprocess.run(["git", "-C", repo, "worktree", "add", path, "-b", name],
                       check=True, capture_output=True)
        return os.path.realpath(path)

    def test_validate_success(self):
        repo = _init_git_repo()
        self.addCleanup(lambda: shutil.rmtree(repo, ignore_errors=True))
        wt = self._make_worktree(repo, "feat")
        artifact = {"status": "ready",
                    "result": {"worktree_path": wt, "branch": "feat"}}
        ok, path, branch, err = cowork.validate_worktree(repo, artifact)
        self.assertTrue(ok, err)
        self.assertEqual(os.path.realpath(path), wt)
        self.assertEqual(branch, "feat")

    def test_validate_failures(self):
        repo = _init_git_repo()
        self.addCleanup(lambda: shutil.rmtree(repo, ignore_errors=True))
        wt = self._make_worktree(repo, "feat")
        # no artifact
        self.assertFalse(cowork.validate_worktree(repo, None)[0])
        # status failed
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "failed", "result": {"error": "boom"}})[0])
        # handoff_back is also a failure (no hand-back partner)
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "handoff_back"})[0])
        # non-absolute path
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "ready",
                   "result": {"worktree_path": "rel/x", "branch": "feat"}})[0])
        # nonexistent path
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "ready",
                   "result": {"worktree_path": "/nope/zzz", "branch": "f"}})[0])
        # missing branch
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "ready", "result": {"worktree_path": wt}})[0])
        # unregistered path (a real dir not registered as a worktree)
        import tempfile
        stray = os.path.realpath(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(stray, ignore_errors=True))
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "ready",
                   "result": {"worktree_path": stray, "branch": "feat"}})[0])
        # branch mismatch
        self.assertFalse(cowork.validate_worktree(
            repo, {"status": "ready",
                   "result": {"worktree_path": wt, "branch": "other"}})[0])


class RunWorktreeTest(unittest.TestCase):
    """run_worktree spawns one agent (injected) and reads back its artifact."""

    def _status_path(self):
        import tempfile
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return os.path.join(d, "worktree.status.json")

    def test_reads_back_agent_artifact(self):
        status = self._status_path()
        sent = {}

        def factory(controller):
            class FakeSession:
                def send(self, text):
                    sent["text"] = text
                    with open(status, "w") as fh:
                        json.dump({"role": "worktree", "status": "ready",
                                   "result": {"worktree_path": "/abs/wt",
                                              "branch": "feat"}}, fh)

                def close(self):
                    sent["closed"] = True
            return FakeSession()

        cfg = {"controller": "codex", "yolo": True, "mode": "implement"}
        artifact = cowork.run_worktree(
            cfg, status, "/base/repo", "feat", True,
            io_out=io.StringIO(), session_factory=factory)
        self.assertEqual(artifact["status"], "ready")
        self.assertEqual(artifact["result"]["branch"], "feat")
        self.assertTrue(sent.get("closed"))
        # the brief carries the base repo, the name, and the explicit policy
        self.assertIn("/base/repo", sent["text"])
        self.assertIn("feat", sent["text"])

    def test_no_artifact_returns_none(self):
        status = self._status_path()

        def factory(controller):
            class FakeSession:
                def send(self, text):
                    pass  # writes nothing

                def close(self):
                    pass
            return FakeSession()

        cfg = {"controller": "codex", "yolo": True, "mode": "implement"}
        artifact = cowork.run_worktree(
            cfg, status, "/base/repo", "auto", False,
            io_out=io.StringIO(), session_factory=factory)
        self.assertIsNone(artifact)


class WorktreeFlowTest(unittest.TestCase):
    def setUp(self):
        import tempfile
        root = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(root, ignore_errors=True))
        old = os.environ.get("COWORK_SESSIONS_ROOT")
        os.environ["COWORK_SESSIONS_ROOT"] = root

        def restore_env():
            if old is None:
                os.environ.pop("COWORK_SESSIONS_ROOT", None)
            else:
                os.environ["COWORK_SESSIONS_ROOT"] = old
        self.addCleanup(restore_env)
        cwd = os.getcwd()
        self.addCleanup(lambda: os.chdir(cwd))

    def _args(self, argv):
        return cowork.build_parser().parse_args(argv)

    def _repo(self):
        repo = _init_git_repo()
        self.addCleanup(lambda: shutil.rmtree(repo, ignore_errors=True))
        return repo

    def _creating_fn(self, calls):
        """A run_worktree_fn that really creates the worktree and records the
        call. Returns a ready artifact pointing at the created path."""
        def fn(wt_config, status_path, base, name, explicit, **kw):
            calls.append({"base": base, "name": name, "explicit": explicit,
                          "controller": wt_config["controller"]})
            path = os.path.join(base, ".worktrees", name)
            subprocess.run(
                ["git", "-C", base, "worktree", "add", path, "-b", name],
                check=True, capture_output=True)
            return {"status": "ready",
                    "result": {"worktree_path": os.path.realpath(path),
                               "branch": name}}
        return fn

    def _creating_fn_sibling(self, calls):
        """A run_worktree_fn that really creates the worktree as a SIBLING
        of the base repo (`../<repo>-worktrees/<name>`) — the OTHER
        convention roles/worktree.md documents when the repo declares none of
        its own. Regression coverage for CAP-BIND-001: a sibling worktree is
        NOT a descendant of the base repo toplevel."""
        def fn(wt_config, status_path, base, name, explicit, **kw):
            calls.append({"base": base, "name": name, "explicit": explicit,
                          "controller": wt_config["controller"]})
            parent = os.path.dirname(base)
            path = os.path.join(
                parent, os.path.basename(base) + "-worktrees", name)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            subprocess.run(
                ["git", "-C", base, "worktree", "add", path, "-b", name],
                check=True, capture_output=True)
            return {"status": "ready",
                    "result": {"worktree_path": os.path.realpath(path),
                               "branch": name}}
        return fn

    def test_gate_outside_git_repo_is_rc2(self):
        import tempfile
        nongit = os.path.realpath(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(nongit, ignore_errors=True))
        os.chdir(nongit)
        scout_calls = []

        def fake_scout(*a, **k):
            scout_calls.append(1)
            return 0
        out = io.StringIO()
        rc = cowork.run_flow(
            self._args(["--worktree", "--team", "scout", "--context", "x",
                        "--no-session"]),
            io_out=out, which=lambda c: "/bin/" + c,
            run_scout_fn=fake_scout,
            run_worktree_fn=lambda *a, **k: self.fail("role ran outside git"))
        self.assertEqual(rc, 2)
        self.assertIn("requires launching inside a git work tree",
                      out.getvalue())
        self.assertEqual(scout_calls, [])  # never reached scouting

    def test_creates_and_redirects_into_worktree(self):
        repo = self._repo()
        os.chdir(repo)
        calls = []
        seen = {}

        def fake_scout(config, context, selected, **kw):
            seen["cwd"] = os.path.realpath(os.getcwd())
            return 0
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--wt-controller", "codex",
                        "--team", "scout,scout-reviewer", "--context", "x", "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=fake_scout,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        # the role ran once, with the single base toplevel and explicit name
        self.assertEqual(len(calls), 1)
        self.assertEqual(calls[0]["base"], repo)
        self.assertEqual(calls[0]["name"], "feat")
        self.assertTrue(calls[0]["explicit"])
        self.assertEqual(calls[0]["controller"], "codex")
        # the session was redirected INTO the created worktree
        self.assertEqual(seen["cwd"],
                         os.path.realpath(os.path.join(repo, ".worktrees",
                                                       "feat")))

    def test_creates_and_redirects_into_sibling_worktree_and_proves(self):
        # CAP-BIND-001 regression: drives the REAL --worktree/run_flow path
        # with a worktree created as a SIBLING of the base repo (the OTHER
        # documented convention, roles/worktree.md), then reproduces the
        # exact real (worktree, worktree_base) facts run_flow computed
        # through the REAL `_compile_role_manifest` compiler + preflight to
        # prove the resulting manifest is proven, not wrongly refused for
        # cwd just because the worktree is not nested under the base repo.
        repo = self._repo()
        os.chdir(repo)
        spath = os.path.join(repo, ".cowork", "session.json")
        calls = []
        captured = {}

        def scout_capture(config, context, selected, session_uuid=None,
                          worktree=None, worktree_base=None, **kw):
            captured["session_uuid"] = session_uuid
            captured["worktree"] = worktree
            captured["worktree_base"] = worktree_base
            captured["cwd"] = os.path.realpath(os.getcwd())
            return 0

        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--wt-controller", "codex",
                        "--team", "scout,scout-reviewer", "--context", "x",
                        "--session-file", spath]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=scout_capture,
            run_worktree_fn=self._creating_fn_sibling(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 1)
        sibling_path = os.path.realpath(os.path.join(
            os.path.dirname(repo), os.path.basename(repo) + "-worktrees",
            "feat"))
        self.assertEqual(captured["cwd"], sibling_path)
        self.assertEqual(captured["worktree"], sibling_path)
        self.assertIsNotNone(captured["session_uuid"])
        self.assertIsNotNone(captured["worktree_base"])
        # The sibling worktree is NOT contained by the base repo toplevel —
        # binding the base repo as the runtime root (the pre-fix behavior)
        # would make every dispatch under this documented convention
        # wrongly refuse.
        self.assertNotEqual(
            os.path.realpath(captured["worktree_base"]),
            os.path.realpath(repo))
        self.assertTrue(
            sibling_path.startswith(
                os.path.realpath(captured["worktree_base"]) + os.sep),
            "the declared runtime root must actually contain the worktree")

        manifest, _ = cowork._compile_role_manifest(
            role="scout", session_uuid=captured["session_uuid"],
            work_id="scout", controller="codex", mode="implement",
            model=None,
            sessions_dir=state_store.session_assets_dir(
                captured["session_uuid"]),
            worktree=captured["worktree"],
            worktree_base=captured["worktree_base"])
        self.assertEqual(
            manifest["status"]["phase"], "proven",
            "a documented sibling-layout worktree must not be refused by "
            "cwd preflight: %r" % (manifest["status"].get("refusal"),))

    def test_validation_failure_no_chdir_rc2(self):
        repo = self._repo()
        os.chdir(repo)
        before = os.path.realpath(os.getcwd())
        scout_calls = []

        def fake_scout(*a, **k):
            scout_calls.append(1)
            return 0
        rc = cowork.run_flow(
            self._args(["--worktree", "--team", "scout", "--context", "x",
                        "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=fake_scout,
            run_worktree_fn=lambda *a, **k: {
                "status": "failed", "result": {"error": "boom"}})
        self.assertEqual(rc, 2)
        self.assertEqual(os.path.realpath(os.getcwd()), before)  # no chdir
        self.assertEqual(scout_calls, [])

    def test_failed_worktree_agent_is_a_failed_run_not_an_invalid_invocation(self):
        repo = self._repo()
        os.chdir(repo)
        before = os.path.realpath(os.getcwd())
        box = {}

        def unscripted(*_a, **_k):
            raise AssertionError("no lead may run after a failed worktree")
        rc = cowork.run_flow(
            self._args(["--worktree", "--team", "scout,scout-reviewer",
                        "--context", "x", "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=unscripted, run_planner_fn=unscripted,
            run_builder_fn=unscripted,
            run_worktree_fn=lambda *a, **k: {
                "status": "failed", "result": {"error": "boom"}},
            result_box=box)
        self.assertEqual((rc, box["reason"]), (1, "worktree_failed"))
        self.assertEqual(cowork.build_run_result(rc, box)["outcome"],
                         "failed")
        self.assertEqual(os.path.realpath(os.getcwd()), before)  # no chdir

    def test_auto_name_default(self):
        repo = self._repo()
        os.chdir(repo)
        calls = []
        rc = cowork.run_flow(
            self._args(["--worktree", "--team", "scout,scout-reviewer", "--context", "x",
                        "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=lambda *a, **k: 0,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        # auto name = cowork-<short session id>; controller defaults to claude
        self.assertTrue(calls[0]["name"].startswith("cowork-"))
        self.assertFalse(calls[0]["explicit"])
        self.assertEqual(calls[0]["controller"], "claude")

    def test_undispatchable_reviewer_is_refused_before_the_worktree_agent(self):
        repo = self._repo()
        os.chdir(repo)
        calls = []
        box = {}
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--config", "scout-reviewer=codex", "--context", "x",
                        "--no-session"]),
            io_out=io.StringIO(),
            which=lambda c: None if c == "codex" else "/bin/" + c,
            run_scout_fn=lambda *a, **k: self.fail("scout must not run"),
            run_worktree_fn=self._creating_fn(calls), result_box=box)
        self.assertEqual((rc, box["reason"]), (1, "reviewer_not_dispatchable"))
        self.assertEqual(calls, [])

    def test_worktree_and_agent_note_compose(self):
        repo = self._repo()
        os.chdir(repo)
        calls = []
        seen = {}

        def fake_scout(config, context, selected, **kw):
            seen["cwd"] = os.path.realpath(os.getcwd())
            seen["agent_note"] = cowork.AGENT_LEAD_NOTE in str(context)
            return 0
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--context", "x", "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=fake_scout,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 1)  # worktree provisioned first
        self.assertTrue(seen["agent_note"])  # then the flow runs inside it
        self.assertEqual(seen["cwd"],
                         os.path.realpath(os.path.join(repo, ".worktrees",
                                                       "feat")))

    def test_resume_reuses_existing_worktree(self):
        repo = self._repo()
        os.chdir(repo)
        spath = os.path.join(repo, ".cowork", "session.json")
        calls = []
        # run 1: creates + records the worktree
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--context", "x", "--session-file", spath]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=lambda *a, **k: 0,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 1)
        saved = state_store.load(spath)
        self.assertIsNotNone(state_store.get_worktree(saved))
        os.chdir(repo)  # run 1 redirected us into the worktree; back to launch
        # run 2 (resume): reuses the recorded worktree, role NOT re-run
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--session-file", spath]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=lambda *a, **k: 0,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 1)  # no second creation

    def test_resume_recreates_when_recorded_worktree_is_stale(self):
        repo = self._repo()
        os.chdir(repo)
        spath = os.path.join(repo, ".cowork", "session.json")
        calls = []
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--context", "x", "--session-file", spath]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=lambda *a, **k: 0,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 1)
        # make the recorded worktree STALE: deregister it from git
        wtpath = os.path.join(repo, ".worktrees", "feat")
        subprocess.run(["git", "-C", repo, "worktree", "remove", "--force",
                        wtpath], check=True, capture_output=True)
        subprocess.run(["git", "-C", repo, "branch", "-D", "feat"],
                       check=True, capture_output=True)
        os.chdir(repo)
        # run 2: recorded path no longer validates -> re-create, never a blind
        # chdir into the stale/unregistered path
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--session-file", spath]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=lambda *a, **k: 0,
            run_worktree_fn=self._creating_fn(calls))
        self.assertEqual(rc, 1)
        self.assertEqual(len(calls), 2)  # re-created, not reused

    def test_agent_runtime_note_in_lead_seed_and_reviewer_context(self):
        repo = self._repo()
        os.chdir(repo)
        seen = {}

        def fake_scout(config, context, selected, reviewer_context=None, **kw):
            seen["context"] = context
            seen["reviewer_context"] = reviewer_context
            return 0
        rc = cowork.run_flow(
            self._args(["--worktree", "feat", "--team", "scout,scout-reviewer",
                        "--context", "GOALTEXT", "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            run_scout_fn=fake_scout,
            run_worktree_fn=self._creating_fn([]))
        self.assertEqual(rc, 1)
        self.assertIn("[agent session]", seen["context"])
        self.assertIn("[agent session]", seen["reviewer_context"])
        # the lead seed still carries the original goal
        self.assertIn("GOALTEXT", seen["context"])

    def test_missing_controller_fails_before_launch(self):
        repo = self._repo()
        os.chdir(repo)
        rc = cowork.run_flow(
            self._args(["--team", "scout,scout-reviewer", "--context", "x",
                        "--no-session"]),
            io_out=io.StringIO(), which=lambda c: None,  # controller missing
            run_scout_fn=lambda *a, **k: self.fail("should not launch scout"))
        self.assertEqual(rc, 1)  # ensure_controller_available returns False


class GitWorkTreePrerequisiteTest(unittest.TestCase):
    """A git work tree is a prerequisite of every cowork run, not a runtime
    condition: each role's write boundary is derived from the launch
    directory's git toplevel, so a launch outside one is refused before any
    session, lease, trace, session asset or dispatch exists."""

    def setUp(self):
        root = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(root, ignore_errors=True))
        old = os.environ.get("COWORK_SESSIONS_ROOT")
        os.environ["COWORK_SESSIONS_ROOT"] = root
        self.sessions_root = root

        def restore_env():
            if old is None:
                os.environ.pop("COWORK_SESSIONS_ROOT", None)
            else:
                os.environ["COWORK_SESSIONS_ROOT"] = old
        self.addCleanup(restore_env)
        cwd = os.getcwd()
        self.addCleanup(lambda: os.chdir(cwd))

    def _args(self, argv):
        return cowork.build_parser().parse_args(argv)

    def _nongit(self):
        d = os.path.realpath(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return d

    def _bare_git(self):
        """A git work tree with no commit — enough to satisfy the gate."""
        d = self._nongit()
        subprocess.run(["git", "init", "-q", d], check=True,
                       capture_output=True)
        return d

    def _no_roles(self):
        """Runner fns that fail the test if the gate lets a run through."""
        def fn(name):
            return lambda *a, **k: self.fail(
                "%s ran from a directory that is not a git work tree" % name)
        return {"run_scout_fn": fn("scout"),
                "run_planner_fn": fn("planner"),
                "run_builder_fn": fn("builder"),
                "run_worktree_fn": fn("worktree")}

    def test_non_git_launch_is_refused_before_any_role(self):
        nongit = self._nongit()
        os.chdir(nongit)
        for cfg in ("scout=claude,yolo,plan", "scout=codex",
                    "scout=opencode,model=anthropic/claude-sonnet-4-5"):
            with self.subTest(config=cfg):
                box = {}
                out = io.StringIO()
                rc = cowork.run_flow(
                    self._args(["--no-session", "--team",
                                "scout,scout-reviewer", "--config", cfg,
                                "--context", "x"]),
                    io_out=out, which=lambda c: "/bin/" + c,
                    result_box=box, **self._no_roles())
                self.assertEqual(rc, 2)
                self.assertEqual(box["reason"], "requires_git_work_tree")
                result = cowork.build_run_result(rc, box)
                self.assertEqual(result["outcome"], "invalid_invocation")
                self.assertEqual(result["rc"], 2)
                self.assertIs(result["approved"], False)
                self.assertEqual(result["reason"], "requires_git_work_tree")
                # Precise and actionable: names the directory and the remedy.
                self.assertIn(nongit, out.getvalue())
                self.assertIn("git init", out.getvalue())

    def test_non_git_refusal_pre_empts_post_gate_refusals_and_creates_nothing(
            self):
        # Non-git leg: the environment diagnosis wins over session selection.
        nongit = self._nongit()
        os.chdir(nongit)
        box = {}
        out = io.StringIO()
        rc = cowork.run_flow(
            self._args(["--resume"]), io_out=out,
            which=lambda c: "/bin/" + c, result_box=box, **self._no_roles())
        self.assertEqual(rc, 2)
        self.assertEqual(box["reason"], "requires_git_work_tree")
        # Nothing was created: the project-local session store would land in
        # the launch directory, and the session asset dir, its trace and the
        # owner lease all land under COWORK_SESSIONS_ROOT/<uuid>/.
        self.assertFalse(os.path.exists(os.path.join(nongit, ".cowork")))
        self.assertEqual(os.listdir(self.sessions_root), [])

        # Git leg: the SAME invocation reaches the session-selection refusal.
        repo = self._bare_git()
        os.chdir(repo)
        box = {}
        out = io.StringIO()
        rc = cowork.run_flow(
            self._args(["--resume"]), io_out=out,
            which=lambda c: "/bin/" + c, result_box=box, **self._no_roles())
        self.assertEqual(rc, 2)
        self.assertEqual(box["reason"], "session_not_found")

    def test_worktree_flag_keeps_its_own_reason_code(self):
        os.chdir(self._nongit())
        box = {}
        rc = cowork.run_flow(
            self._args(["--worktree", "--team", "scout", "--context", "x",
                        "--no-session"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            result_box=box, **self._no_roles())
        self.assertEqual(rc, 2)
        # The flag-specific diagnosis keeps its earlier position and its own
        # code; the general prerequisite code must NOT replace it.
        self.assertEqual(box["reason"], "worktree_requires_git")

    def test_git_launch_reaches_scouting(self):
        repo = _init_git_repo()
        self.addCleanup(lambda: shutil.rmtree(repo, ignore_errors=True))
        os.chdir(repo)
        calls = []

        def fake_scout(*a, **k):
            calls.append(1)
            return 0
        box = {}
        rc = cowork.run_flow(
            self._args(["--no-session", "--team", "scout,scout-reviewer",
                        "--config", "scout=claude,yolo,plan",
                        "--context", "x"]),
            io_out=io.StringIO(), which=lambda c: "/bin/" + c,
            result_box=box, run_scout_fn=fake_scout,
            run_worktree_fn=lambda *a, **k: self.fail("no worktree requested"))
        self.assertEqual(calls, [1])
        self.assertNotEqual(rc, 2)
        self.assertNotEqual(box.get("reason"), "requires_git_work_tree")

    def test_readme_documents_the_git_prerequisite(self):
        readme = os.path.join(os.path.dirname(_HERE), "README.md")
        with open(readme, "r") as fh:
            text = " ".join(fh.read().split())  # collapse markdown wrapping
        for literal in (
                "every cowork run must be launched inside a git work tree",
                "refused before anything is dispatched "
                "(rc 2, `reason: requires_git_work_tree`)",
                "**any folder inside a git work tree**",
                "rc 2 and `reason: requires_git_work_tree`",
                "`requires_git_work_tree` (rc 2) pre-empts them",
                "worktree_requires_git"):
            with self.subTest(literal=literal):
                self.assertIn(literal, text)
        # The uncorrected claim that cowork runs from any folder at all.
        self.assertNotIn("**any folder**", text)


class WorktreeStateTest(unittest.TestCase):
    def _tmp(self):
        import tempfile
        d = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(d, ignore_errors=True))
        return os.path.join(d, ".cowork", "session.json")

    def test_set_and_get_worktree_roundtrip(self):
        spath = self._tmp()
        state = state_store.ensure_session(spath, None, "S")
        self.assertIsNone(state_store.get_worktree(state))
        state = state_store.set_worktree(spath, "/abs/wt", "feat", prior=state)
        got = state_store.get_worktree(state)
        self.assertEqual(got, {"path": "/abs/wt", "branch": "feat"})
        # survives a reload
        self.assertEqual(state_store.get_worktree(state_store.load(spath)),
                         {"path": "/abs/wt", "branch": "feat"})

    def test_resume_discovery_is_cwd_relative(self):
        # D3 resume-from-launch-dir: the session store is discovered from the
        # cwd, so a session created at the launch dir is NOT found from inside a
        # (sibling) worktree dir — confirming resume must be from the launch dir.
        import tempfile
        launch = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(launch, ignore_errors=True))
        worktree = tempfile.mkdtemp()
        self.addCleanup(lambda: shutil.rmtree(worktree, ignore_errors=True))
        state_store.ensure_session(
            state_store.session_path(launch), None, "S")
        self.assertTrue(state_store.discover_session_files(launch))
        self.assertEqual(state_store.discover_session_files(worktree), [])


